const DOCUMENTED_BANK=[{"id":"AG-2ESO-001","topic":"enteros","unit":1,"level":3,"stem":"En un taller se revisan tres máquinas cada 12, 18 y 30 horas. Acaban de revisarse las tres a la vez. ¿Cuántas horas transcurrirán hasta que coincidan de nuevo las tres revisiones?","answer":"180 horas","solution":"mcm(12; 18; 30)=2²·3²·5=180.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-002","topic":"enteros","unit":1,"level":3,"stem":"Un ascensor parte de la planta −4, sube 9 plantas, baja 7 y vuelve a subir 5. ¿En qué planta termina?","answer":"3","solution":"−4+9−7+5=3.","origin":"original","source":"Navarra","sourceUrl":"https://www.educacion.navarra.es/en/web/dpto/evaluacion-y-calidad/evaluacion/evaluacion-externa/evaluacion-de-navarra/educacion-secundaria-curso-2024-2025","review":"revisión docente recomendada"},{"id":"AG-2ESO-003","topic":"fracciones","unit":2,"level":4,"stem":"Un depósito está lleno hasta los 3/4 de su capacidad. Se consume 1/3 del agua que contiene y luego se añaden 20 litros, quedando lleno hasta los 2/3. ¿Cuál es su capacidad?","answer":"120 litros","solution":"(3/4)·(2/3)C+20=(2/3)C; C/2+20=2C/3; C=120.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-004","topic":"fracciones","unit":2,"level":3,"stem":"Para una excursión se ha reservado 2/5 de las plazas de un autobús a un grupo y 1/3 a otro. Si el autobús tiene 60 plazas, ¿cuántas quedan libres?","answer":"16 plazas","solution":"1−2/5−1/3=4/15; 60·4/15=16.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-005","topic":"polinomios","unit":3,"level":4,"stem":"Un rectángulo tiene base 2x+3 y altura x−1. Escribe su área como polinomio reducido e indica para qué valores enteros de x mayores que 1 el área es 18.","answer":"Área: 2x²+x−3; x=3","solution":"(2x+3)(x−1)=2x²+x−3. Para x=3: 18. Otra raíz es −7/2, que no cumple.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-006","topic":"lenguaje","unit":3,"level":3,"stem":"La edad de un hermano es tres años mayor que el doble de la edad de su hermana. Dentro de cuatro años, la suma de sus edades será 41. ¿Qué edades tienen ahora?","answer":"Hermana 10; hermano 23","solution":"h=2m+3; (m+4)+(h+4)=41; 3m+11=41; m=10, h=23.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-007","topic":"eq_denominadores","unit":4,"level":4,"stem":"Resuelve y comprueba: (x−3)/2 − (x+1)/3 = (x−5)/6 + 2.","answer":"No tiene solución","solution":"Multiplica por 6: 3x−9−2x−2=x−5+12; x−11=x+7; contradicción.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-008","topic":"eq_segundo","unit":4,"level":4,"stem":"Resuelve la ecuación 3x²−75=0 e indica las dos soluciones.","answer":"x=−5 y x=5","solution":"3x²=75; x²=25; x=±5.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-009","topic":"eq_segundo","unit":4,"level":4,"stem":"Resuelve x²−7x=0 e indica ambas soluciones.","answer":"x=0 y x=7","solution":"x(x−7)=0.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-010","topic":"sistemas","unit":5,"level":5,"stem":"En un centro han comprado 32 entradas para una actividad: unas de adulto a 12 € y otras de estudiante a 7 €. Pagan en total 274 €. ¿Cuántas entradas de cada tipo han comprado?","answer":"10 de adulto y 22 de estudiante","solution":"a+e=32; 12a+7e=274; 5a=50; a=10, e=22.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-011","topic":"prop_compuesta","unit":6,"level":5,"stem":"Cinco máquinas iguales fabrican 300 piezas en 4 horas. ¿Cuántas piezas fabricarán 8 máquinas en 7 horas si mantienen el mismo ritmo?","answer":"840 piezas","solution":"300/(5·4)=15 piezas por máquina y hora; 8·7·15=840.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-012","topic":"reparto_inverso","unit":6,"level":5,"stem":"Se reparten 780 € entre tres personas de forma inversamente proporcional a 2, 3 y 6. ¿Cuánto recibe cada una?","answer":"390 €, 260 € y 130 €","solution":"Proporciones 1/2:1/3:1/6 equivalen a 3:2:1; 780/6=130.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-013","topic":"porc_encadenados","unit":6,"level":4,"stem":"Un producto cuesta 200 €. Primero se rebaja un 20 % y después se aplica una rebaja adicional del 25 % sobre el nuevo precio. ¿Cuál es el precio final?","answer":"120 €","solution":"200·(4/5)·(3/4)=120.","origin":"original","source":"Navarra","sourceUrl":"https://www.educacion.navarra.es/en/web/dpto/evaluacion-y-calidad/evaluacion/evaluacion-externa/evaluacion-de-navarra/educacion-secundaria-curso-2024-2025","review":"revisión docente recomendada"},{"id":"AG-2ESO-014","topic":"funciones","unit":7,"level":4,"stem":"La distancia a casa de una ciclista sigue esta tabla: a las 0 h está a 0 km, a la 1 h a 12 km, a las 2 h a 12 km y a las 3 h a 0 km. ¿Durante qué intervalo se detiene y cuál es la rapidez media del trayecto completo?","answer":"Parada entre 1 h y 2 h; rapidez media 8 km/h","solution":"Recorre 12+12=24 km en 3 horas; 24/3=8.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-015","topic":"lineales","unit":8,"level":4,"stem":"Un servicio de alquiler cobra 6 € fijos y 4 € por hora. Escribe el coste C(h). Si otro servicio cobra 10 € fijos y 3 € por hora, ¿a partir de cuántas horas el segundo servicio es más barato?","answer":"C(h)=6+4h; para h>4","solution":"6+4h>10+3h si h>4; a las 4 horas cuestan lo mismo.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-016","topic":"datos","unit":9,"level":4,"stem":"En un centro hay 50 alumnos de 1.º ESO y 70 de 2.º ESO. En 1.º hay 28 alumnas y en 2.º hay 35 alumnas. Si se elige al azar a una persona de los dos cursos, ¿qué probabilidad hay de que sea alumna de 2.º ESO?","answer":"7/24","solution":"35/(50+70)=35/120=7/24.","origin":"original","source":"Navarra","sourceUrl":"https://www.educacion.navarra.es/en/web/dpto/evaluacion-y-calidad/evaluacion/evaluacion-externa/evaluacion-de-navarra/educacion-secundaria-curso-2024-2025","review":"revisión docente recomendada"},{"id":"AG-2ESO-017","topic":"estadistica","unit":9,"level":3,"stem":"Las puntuaciones de siete participantes son 8, 11, 8, 15, 12, 9 y 14. Calcula la media, mediana y moda.","answer":"Media 11; mediana 11; moda 8","solution":"Suma 77, 77/7=11. Ordenados 8, 8, 9, 11, 12, 14, 15.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-018","topic":"pitagoras","unit":10,"level":4,"stem":"Una escalera de 13 metros apoya su extremo superior en una pared a 12 metros del suelo. ¿A qué distancia de la pared está su base?","answer":"5 metros","solution":"13²−12²=25; √25=5.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-019","topic":"semejanza","unit":10,"level":5,"stem":"Dos triángulos semejantes tienen una razón de semejanza 3/2 (del pequeño al grande). Si el área del pequeño es 24 cm², ¿cuál es el área del grande?","answer":"54 cm²","solution":"Las áreas se multiplican por (3/2)²=9/4; 24·9/4=54.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-020","topic":"superficies","unit":11,"level":4,"stem":"Un prisma recto de base cuadrada tiene lado de base 6 cm y altura 10 cm. ¿Cuál es su área total?","answer":"312 cm²","solution":"Dos bases de área 36 y cuatro caras laterales de 60: 72+240=312.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"},{"id":"AG-2ESO-021","topic":"volumen","unit":12,"level":4,"stem":"Un depósito cilíndrico tiene radio interior de 3 dm y altura de 8 dm. ¿Cuál es su volumen exacto y a cuántos litros equivale?","answer":"72π dm³ = 72π litros","solution":"V=π·3²·8=72π dm³. Un dm³ equivale a un litro.","origin":"original","source":"Navarra","sourceUrl":"https://www.educacion.navarra.es/en/web/dpto/evaluacion-y-calidad/evaluacion/evaluacion-externa/evaluacion-de-navarra/educacion-secundaria-curso-2024-2025","review":"revisión docente recomendada"},{"id":"AG-2ESO-022","topic":"volumen","unit":12,"level":5,"stem":"Un cono y un cilindro tienen la misma base y altura. Si el cilindro tiene volumen de 180π cm³, ¿cuánto volumen tiene el cono y cuál es la diferencia de volúmenes?","answer":"Cono 60π cm³; diferencia 120π cm³","solution":"V_cono=V_cilindro/3=60π; 180π−60π=120π.","origin":"original","source":"Intergranada","sourceUrl":"https://selectividad.intergranada.com/mates2eso.html","review":"revisión docente recomendada"}];
