const signedTerm=(n)=>n<0?` − ${-n}`:` + ${n}`;
const rational=(n,d)=>{const g=gcd(n,d);return d/g===1?String(n/g):`${n/g}/${d/g}`};
// Cada solución se construye desde valores elegidos y se comprueba sustituyendo.
function makeAlgebra(topic,level){let x=randint(-6,12),a=randint(2,7),b=randint(2,9),c=randint(2,6),d=randint(2,7),y=randint(-5,10),k=randint(1,5),v,stem,solution,hint,form;
 if(topic==='lenguaje'){
  const variant=randint(0,3);
  if(variant===0){const n=randint(2,8),t=randint(2,8);v=n*t+b;stem=`El triple de un número, más ${b}, se expresa como 3x + ${b}. ¿Cuánto vale la expresión si x=${t}?`;v=3*t+b;solution=`Sustituimos: 3·${t}+${b}=${v}.`;hint='Sustituye x por el número indicado.';form='evaluar'}
  else if(variant===1){v=a*x+b;stem=`Una tarifa tiene un coste fijo de ${b} € y cobra ${a} € por entrada. Si se compran ${x+8} entradas, ¿cuál es el coste total?`;v=a*(x+8)+b;solution=`C(n)=${a}n+${b}; C(${x+8})=${v} €.`;hint='Construye primero una expresión general.';form='modelar'}
  else if(variant===2){v=(a+b)*c;stem=`Un rectángulo de lados x+${b} y x+${a}, con x=${c}, tiene un perímetro de cuántas unidades?`;v=2*((c+b)+(c+a));solution=`P=2[(x+${b})+(x+${a})]. Sustituimos x=${c}: P=${v}.`;hint='Suma los cuatro lados, no solo dos.';form='perimetro'}
  else{v=a*x+b;stem=`Una sucesión sigue la regla a(n)=${a}n+${b}. ¿Cuál es el término en la posición ${x+8}?`;v=a*(x+8)+b;solution=`a(${x+8})=${a}·${x+8}+${b}=${v}.`;hint='La posición es la variable n.';form='patrones'}
  if(level===5){const step=randint(3,8),first=randint(2,9),n=randint(10,30),target=first+(n-1)*step;return {...q(topic,level,`Una sucesión aritmética empieza en ${first} y aumenta ${step} en cada término. ¿Qué posición ocupa el valor ${target}?`,n,`a(k)=${first}+${step}(k−1). Igualando a ${target} resulta k=${n}.`,'Plantea la regla del término general y despeja la posición.'),family:'invertir-patron'};}
  if(level===1){let z=randint(2,12);return {...q(topic,level,`Si x=${z}, calcula x+${b}.`,z+b,`x+${b}=${z}+${b}=${z+b}.`,'Sustituye la letra por su valor.'),family:'sustitucion'};}
  if(level===2){let z=randint(3,11);return {...q(topic,level,`Si x=${z}, calcula ${a}x+${b}.`,a*z+b,`${a}·${z}+${b}=${a*z+b}.`,'Multiplica antes de sumar.'),family:'expresion'};}
  if(level>=4&&form==='evaluar'){v=a*(x+8)+b;stem=`Un proveedor cobra ${b} € por pedido y ${a} € por unidad. ¿Cuánto se paga por ${x+8} unidades?`;solution=`C(n)=${a}n+${b}; C(${x+8})=${v}.`;form='modelar';}
  return {...q(topic,level,stem,v,solution,hint),family:form};
 }
 if(topic==='eq_basicas'){
  const variant=level===1?0:randint(0,3);let lhs,rhs;
  if(variant===0){lhs=`${a}x + ${b}`;rhs=a*x+b;form='lineal';}
  else if(variant===1){lhs=`${a}x − ${b}`;rhs=a*x-b;form='resta';}
  else if(variant===2){lhs=`${a}x + ${b}`;rhs=a*x+b;form='lineal';if(level>=4){lhs=`${a}x + ${b}`;rhs=a*x+b;}}
  else{const m=a+randint(1,4);lhs=`${m}x − ${a}x + ${b}`;rhs=(m-a)*x+b;form='reducir';}
  if(level>=4&&randint(0,1)){const m=randint(1,3),right=(a-m)*x+b;lhs=`${a}x + ${b} = ${m}x + ${right}`;stem=`Resuelve: ${lhs}`;solution=`Agrupa las x: (${a}−${m})x=${right-b}; x=${x}.`;form='dos-miembros';}
  else{stem=`Resuelve: ${lhs} = ${rhs}`;solution=`Al despejar y comprobar la igualdad obtenemos x=${x}.`;}
  if(level===5){const m=a+2;stem=`Un número cumple ${m}x − ${a}x + ${b} = ${2*x+b}. ¿Cuál es el valor de x?`;solution=`La igualdad ${m}x−${a}x+${b}=${2*x+b} es cierta para cualquier x: por tanto hay infinitas soluciones. (Ejercicio no evaluable por respuesta numérica.)`;return makeAlgebra(topic,4);}
  return {...q(topic,level,stem,x,solution,'Agrupa los términos con x y comprueba sustituyendo.'),family:form};
 }
 if(topic==='eq_parentesis'){
  const variant=randint(0,3);let rhs, lhs;
  if(level===1){lhs=`${a}(x + ${b})`;rhs=a*(x+b);form='distributiva';}
  else if(variant===0){lhs=`${a}(x + ${b}) − ${c}`;rhs=a*(x+b)-c;form='un-par';}
  else if(variant===1){lhs=`${a}(x − ${b}) + ${c}`;rhs=a*(x-b)+c;form='negativo';}
  else if(variant===2){lhs=`${a}(x + ${b}) − ${c}(x − ${d})`;rhs=a*(x+b)-c*(x-d);form='doble'; if(a===c){a+=1;lhs=`${a}(x + ${b}) − ${c}(x − ${d})`;rhs=a*(x+b)-c*(x-d)}}
  else{let m=randint(1,a-1);lhs=`${a}(x − ${b}) = ${m}(x + ${c}) ${signedTerm(a*(x-b)-m*(x+c))}`;rhs=null;form='dos-par';}
  stem=`Resuelve: ${lhs}${rhs===null?'':` = ${rhs}`}`;
  solution=`Distribuye los paréntesis, reúne términos semejantes y despeja x. El resultado es x=${x}; compruébalo en la igualdad.`;
  return {...q(topic,level,stem,x,solution,'Aplica correctamente la distributiva, incluidos los signos negativos.'),family:form};
 }
 if(topic==='eq_denominadores'){
  const den1=randint(2,5),den2=randint(2,5),offset=randint(1,7);let rhs,coef,stem2,ans;
  if(level===1){ans=randint(2,9);stem=`Resuelve: x/${den1} = ${ans}`;return {...q(topic,level,stem,ans*den1,`Multiplica por ${den1}: x=${ans*den1}.`,'Elimina el denominador.'),family:'simple'};}
  if(level===2){ans=randint(2,10);stem=`Resuelve: (x + ${offset})/${den1} = ${ans}`;return {...q(topic,level,stem,ans*den1-offset,`x+${offset}=${den1*ans}; x=${ans*den1-offset}.`,'Multiplica ambos miembros por el denominador.'),family:'uno'};}
  if(level===3){stem=`Resuelve: (x + ${offset})/${den1} = ${rational(x+offset,den1)}`;form='uno';}
  else if(level===4){rhs=(x+offset)/den1+x/den2;stem=`Resuelve: (x + ${offset})/${den1} + x/${den2} = ${rational((x+offset)*den2+x*den1,den1*den2)}`;form='dos';}
  else {const m=randint(1,4),d3=randint(2,6),d4=randint(2,6),t=randint(1,5);
   // Tres fracciones a la izquierda, dos a la derecha, con restas y solución entera construida.
   const lhs=(x+offset)/den1 - (x-m)/den2 + (x+t)/d3;
   const rhsExtra=(x-t)/d4;
   const constant=lhs-rhsExtra;
   stem=`Resuelve: (x + ${offset})/${den1} − (x − ${m})/${den2} + (x + ${t})/${d3} = (x − ${t})/${d4} + ${rational(Math.round(constant*den1*den2*d3*d4),den1*den2*d3*d4)}`;
   form='cinco-fracciones';
   // Coeficiente no nulo para asegurar solución única.
   const coeff=1/den1-1/den2+1/d3-1/d4;
   if(Math.abs(coeff)<1e-9)return makeAlgebra(topic,level);
  }
  // Evita igualdad sin incógnita en la resta con denominadores iguales.
  return {...q(topic,level,stem,x,`Multiplica por un múltiplo común de los denominadores, agrupa y despeja. x=${x}. Comprueba sustituyendo.`,'Multiplica TODOS los términos por el m.c.m. de los denominadores.'),family:form};
 }
 if(topic==='eq_mixtas'){
  let den1=randint(2,4),den2=randint(3,6),p=randint(1,5),m=randint(2,5),r;
  if(level===1){stem=`Resuelve: ${a}(x + ${b}) = ${a*(x+b)}`;form='par';}
  else if(level===2){stem=`Resuelve: (${a}x + ${b})/${den1} = ${rational(a*x+b,den1)}`;form='frac';}
  else if(level===3){r=(a*(x+b))/den1;stem=`Resuelve: ${a}(x + ${b})/${den1} = ${rational(a*(x+b),den1)}`;form='distributiva-frac';}
  else if(level===4){r=a*(x+b)/den1+x/den2;stem=`Resuelve: ${a}(x + ${b})/${den1} + x/${den2} = ${rational(a*(x+b)*den2+x*den1,den1*den2)}`;form='doble-frac';}
  else{const den3=randint(2,5),den4=randint(3,7),tt=randint(1,5);
    const lhs=a*(x+b)/den1-(x-m)/den2;
    const rSide=(x+tt)/den3-(x-tt)/den4;
    const constant=lhs-rSide;
    stem=`Resuelve: ${a}(x + ${b})/${den1} − (x − ${m})/${den2} = (x + ${tt})/${den3} − (x − ${tt})/${den4} + ${rational(Math.round(constant*den1*den2*den3*den4),den1*den2*den3*den4)}`;
    const coeff=a/den1-1/den2-1/den3+1/den4;
    if(Math.abs(coeff)<1e-9)return makeAlgebra(topic,level);
    form='cuatro-fracciones-resta';
   }
  return {...q(topic,level,stem,x,`Quita denominadores, aplica distributiva y reduce términos. La solución es x=${x}. Sustituye para verificar.`,'El m.c.m. elimina denominadores antes de despejar.'),family:form};
 }
 if(topic==='eq_segundo'){
  // Raíces enteras fabricadas; pregunta numérica inequívoca por una de ellas.
  let r1=randint(-7,-1),r2=randint(2,9),sm=r1+r2,pr=r1*r2;
  if(level===1){r1=randint(2,9);stem=`Si x²=${r1*r1}, ¿cuál es la solución positiva?`;return {...q(topic,level,stem,r1,`x=±${r1}. La positiva es ${r1}.`,'Una raíz cuadrada tiene dos signos en una ecuación.'),family:'cuadrado'};}
  if(level===2){r1=randint(2,9);stem=`Resuelve x(x − ${r1})=0. ¿Cuál es la solución distinta de cero?`;return {...q(topic,level,stem,r1,`Producto nulo: x=0 o x=${r1}.`,'Si un producto es cero, algún factor es cero.'),family:'producto'};}
  if(level===3&&randint(0,1)===0){const rt=randint(2,9);stem=`Ecuación incompleta (b=0): x² − ${rt*rt}=0. ¿Cuál es la raíz positiva?`;return {...q(topic,level,stem,rt,`x²=${rt*rt}; x=±${rt}. Se pide la positiva: ${rt}.`,'Aísla el cuadrado y considera ambos signos.'),family:'incompleta-b0'};}
  if(level===3){stem=`La ecuación x² ${signedTerm(-sm)}x ${signedTerm(pr)} = 0 tiene dos raíces enteras. ¿Cuál es la mayor?`;form='factorizar';}
  else if(level===4&&randint(0,2)===0){const rt=randint(2,9),aa=randint(2,5);stem=`Ecuación incompleta (c=0): ${aa}x² − ${aa*rt}x = 0. ¿Cuál es la solución distinta de cero?`;return {...q(topic,level,stem,rt,`Factor común: ${aa}x(x−${rt})=0. Soluciones: 0 y ${rt}.`,'Extrae factor común x.'),family:'incompleta-c0'};}
  else if(level===4){const aa=randint(2,4);stem=`La ecuación ${aa}x² ${signedTerm(-aa*sm)}x ${signedTerm(aa*pr)} = 0 tiene dos soluciones. ¿Cuál es la mayor?`;form='coeficiente';}
  else{const shift=randint(1,4);stem=`Resuelve (x − ${shift})² ${signedTerm(-sm)}(x − ${shift}) ${signedTerm(pr)} = 0. ¿Cuál es la solución mayor?`;r2+=shift;r1+=shift;form='cambio-variable';}
  solution=`La ecuación se factoriza a partir de las dos raíces. Solución mayor: ${r2} (la otra es ${r1}).`;
  return {...q(topic,level,stem,r2,solution,'Busca dos números cuyo producto y suma correspondan a los coeficientes.'),family:form};
 }
 if(topic==='sistemas'){
  x=randint(2,12);y=randint(1,10);const variant=randint(0,3);let A,B,C,D,E,F;
  if(level===1){stem=`Si x+y=${x+y} y x=${x}, ¿cuánto vale y?`;return {...q(topic,level,stem,y,`y=${x+y}−${x}=${y}.`,'Sustituye el dato conocido.'),family:'sustitucion'};}
  if(level===2){stem=`En el sistema x+y=${x+y}, x−y=${x-y}, ¿cuánto vale x?`;return {...q(topic,level,stem,x,`Sumando las ecuaciones: 2x=${2*x}, x=${x}.`,'Suma las ecuaciones.'),family:'suma-resta'};}
  if(level===3){stem=`En el sistema 2x+y=${2*x+y}, x+y=${x+y}, ¿cuánto vale y?`;return {...q(topic,level,stem,y,`Restando se obtiene x=${x}, luego y=${y}.`,'Resta ambas ecuaciones para eliminar una incógnita.'),family:'eliminar'};}
  if(level===4){let aa=randint(2,4);stem=`En el sistema ${aa}x+y=${aa*x+y}, x−y=${x-y}, ¿cuánto vale x?`;form='coeficientes';}
  else{let aa=randint(2,4),bb=randint(2,4);stem=`En el sistema ${aa}x+${bb}y=${aa*x+bb*y}, x−y=${x-y}, ¿cuánto vale x?`;form='dos-coeficientes';}
  return {...q(topic,level,stem,x,`Eliminando una incógnita se obtiene x=${x}, y después y=${y}. Verifica las dos ecuaciones.`,'Multiplica una ecuación si hace falta y elimina la otra incógnita.'),family:form};
 }
 throw Error('Subtema de álgebra no disponible');
}
// Cada apartado tiene una familia propia de ejercicios parametrizados y solución exacta.
const PROP_IDS=['prop_directa','prop_inversa','prop_compuesta','porcentajes','porc_encadenados','reparto_directo','reparto_inverso'];
function makeProportion(topic,level){
 let a,b,c,d,k,total,ans,stem,solution,hint;
 if(topic==='prop_directa'){
  k=randint(2,12);a=randint(2,8);b=randint(a+1,a+12);
  if(level===1)return {...q(topic,level,`Si ${a} cuadernos cuestan ${a*k} €, ¿cuánto cuestan ${b} cuadernos?`,b*k,`Cada cuaderno cuesta ${k} €. ${b}·${k}=${b*k} €.`,`Calcula el precio por unidad.`),family:'precio-unitario'};
  if(level===2)return {...q(topic,level,`Una receta para ${a} personas emplea ${a*k} g de un ingrediente. ¿Cuántos gramos necesitarás para ${b} personas?`,b*k,`Tasa: ${a*k}/${a}=${k} g por persona. Para ${b}, ${b*k} g.`,`El cociente gramos/personas es constante.`),family:'receta'};
  if(level===3)return {...q(topic,level,`En un plano de escala 1:${k*100}, un camino mide ${a} cm. ¿Cuántos metros mide realmente?`,a*k,`${a}·${k*100} cm=${a*k*100} cm=${a*k} m.`,`Pasa primero a centímetros reales y después a metros.`),family:'escala'};
  if(level===4){total=randint(4,10)*k;return {...q(topic,level,`Una máquina consume ${a*k} litros de combustible para producir ${a*total} unidades. ¿Cuántos litros necesita para producir ${b*total} unidades al mismo rendimiento?`,b*k,`Consumo por unidad: ${a*k}/${a*total}=${k}/${total}. Para ${b*total} unidades: ${b*k} L.`,`Comprueba que el cociente litros/unidades no cambia.`),family:'rendimiento'};}
  c=randint(2,6);return {...q(topic,level,`Una tarifa proporcional cobra ${a*k} € por ${a} horas. Otra oferta cobra ${b*k+c} € por ${b} horas. ¿Cuánto se ahorra con la primera para ${b} horas?`,c,`La primera tarifa cobra ${k} €/h: ${b*k} €. La segunda cuesta ${b*k+c} €. Diferencia: ${c} €.`,`Calcula el coste con el precio unitario antes de comparar.`),family:'comparar-tarifas'};
 }
 if(topic==='prop_inversa'){
  a=randint(3,7);b=randint(3,9);c=randint(2,4);total=a*b;
  if(level===1)return {...q(topic,level,`${a} trabajadores terminan una tarea en ${b*c} días. ¿Cuántos días necesitarían ${a*c} trabajadores para hacerla, con el mismo rendimiento individual y la misma jornada diaria?`,b,`${a}·${b*c}=${a*c}·d; d=${b} días.`,`El producto trabajadores·días se mantiene.`),family:'trabajadores',verification:{units1:a,units2:a*c,time1:b*c,time2:b,requested:'time'}};
  if(level===2)return {...q(topic,level,`Un depósito se vacía en ${b*c} horas con ${a} bombas iguales. ¿Cuántas horas tardarían ${a*c} bombas en vaciar el mismo depósito, con el mismo caudal por bomba?`,b,`${a}·${b*c}=${a*c}·t. t=${b} h.`,`Más bombas implican menos tiempo.`),family:'bombas',verification:{units1:a,units2:a*c,time1:b*c,time2:b,requested:'time'}};
  if(level===3){
   const pair=pick([[30,60],[40,80],[60,90],[60,120]]),v1=pair[0],v2=pair[1],distance=v1*v2/gcd(v1,v2)*randint(1,3),t1=distance/v1,t2=distance/v2;
   return {...q(topic,level,`Un vehículo recorre ${distance} km en ${t1} ${t1===1?'hora':'horas'}. ¿A qué velocidad debe circular para recorrer la misma distancia en ${t2} ${t2===1?'hora':'horas'}? En ambos viajes mantiene una velocidad constante y no hace paradas. Responde en km/h.`,v2,`Velocidad inicial: ${distance}/${t1}=${v1} km/h. Para la misma distancia, velocidad y tiempo son inversamente proporcionales: ${v1}·${t1}=v·${t2}. Velocidad nueva: ${distance}/${t2}=${v2} km/h. Comprobación: ${v2}·${t2}=${distance} km.`,`La velocidad no está dada: calcúlala dividiendo la distancia entre el tiempo. Mantén la misma distancia en ambos viajes.`),family:'velocidad',verification:{distance,v1,v2,t1,t2,requested:'speed'}};

  }
  if(level===4){d=randint(2,5);return {...q(topic,level,`Un equipo de ${a*c} personas puede realizar una tarea en ${b} días. Antes de empezar, ${a*(c-1)} personas dejan el equipo. ¿Cuántos días necesitarán las restantes para hacer la tarea completa, con el mismo rendimiento individual y la misma jornada diaria?`,b*c,`Quedan ${a} personas. Trabajo total: ${a*c}·${b}=${a}·t ⇒ t=${b*c} días.`,`Determina primero cuántas personas quedan.`),family:'ausencias',verification:{units1:a*c,units2:a,time1:b,time2:b*c,requested:'time'}};}
  const pair=pick([[60,30],[80,40],[90,60],[120,60]]),v1=pair[0],v2=pair[1],distance=v1*v2/gcd(v1,v2)*randint(1,3),t1=distance/v1,t2=distance/v2;
  return {...q(topic,level,`Un vehículo recorre ${distance} km en ${t2} horas. Quiere completar la misma ruta en ${t1} ${t1===1?'hora':'horas'}. ¿Cuántos km/h debe aumentar su velocidad? En ambos viajes mantiene una velocidad constante y no hace paradas.`,v1-v2,`Velocidad inicial: ${distance}/${t2}=${v2} km/h. Velocidad necesaria: ${distance}/${t1}=${v1} km/h. Aumento: ${v1}−${v2}=${v1-v2} km/h. Comprobación: ${v1}·${t1}=${v2}·${t2}=${distance} km.`,`Calcula las dos velocidades dividiendo la distancia por cada tiempo. Después resta la inicial de la necesaria.`),family:'cambio-velocidad',verification:{distance,v1,v2,t1,t2,requested:'speedDifference'}};


 }
 if(topic==='prop_compuesta'){
  a=randint(2,6);b=randint(2,6);c=randint(2,4);d=randint(2,4);k=randint(2,8);
  if(level===1)return {...q(topic,level,`${a} máquinas fabrican ${a*b*k} piezas en ${b} horas. ¿Cuántas piezas fabrican ${a*c} máquinas en las mismas ${b} horas?`,a*c*b*k,`Producción unitaria: ${k} piezas por máquina·hora. Resultado ${a*c*b*k}.`,`Primero calcula las piezas por máquina y hora.`),family:'maquinas-fijas'};
  if(level===2)return {...q(topic,level,`${a} máquinas producen ${a*b*k} piezas en ${b} horas. ¿Cuántas piezas producen ${a*c} máquinas en ${b*d} horas?`,a*c*b*d*k,`Tasa ${k} por máquina y hora; ${a*c}·${b*d}·${k}=${a*c*b*d*k}.`,`Aquí ambas magnitudes son directas respecto a las piezas.`),family:'produccion-dd'};
  if(level===3)return {...q(topic,level,`${a} operarios tardan ${b*d} días trabajando ${c} horas diarias en un encargo. ¿Cuántos días necesitan ${a*d} operarios trabajando las mismas ${c} horas al día?`,b,`Trabajo fijo: ${a}·${b*d}·${c}=${a*d}·t·${c}; t=${b}.`,`El tiempo es inverso al número de operarios.`),family:'operarios-inversa'};
  if(level===4)return {...q(topic,level,`${a} operarios terminan una obra en ${b*d} días trabajando ${c*d} horas diarias. ¿Cuántos días necesitan ${a*d} operarios trabajando ${c} horas al día al mismo ritmo?`,b*d,`Trabajo total: ${a}·${b*d}·${c*d}; nuevo ritmo diario ${a*d}·${c}; días =${b*d}.`,`Trabajadores y horas/día son inversos respecto a los días.`),family:'trabajo-mixto'};
  return {...q(topic,level,`${a} operarios fabrican ${a*b*c*k} piezas en ${b} días de ${c} horas. Si deben fabricar el doble con ${a*d} operarios, jornadas de ${c*2} horas y la misma productividad, ¿cuántos días necesitan?`,b/d,`Tasa ${k} piezas por operario y hora. Objetivo ${2*a*b*c*k}; capacidad diaria ${a*d*c*2*k}; días ${fmt(b/d)}.`,`Relaciona producción con operarios, días y horas por jornada.`),family:'inversa-mixta-meta'};
 }
 if(topic==='porcentajes'){
  a=pick([10,15,20,25,30,40]);b=randint(4,18)*20;
  if(level===1)return {...q(topic,level,`¿Cuánto es el ${a}% de ${b} €?`,a*b/100,`${b}·${a}/100=${fmt(a*b/100)} €.`,`Expresa el porcentaje como fracción de 100.`),family:'parte'};
  if(level===2)return {...q(topic,level,`Un artículo cuesta ${b} €. Con descuento del ${a}%, ¿cuánto pagas?`,b*(1-a/100),`${b}·(1−${a}/100)=${fmt(b*(1-a/100))} €.`,`Calcula el porcentaje que sí se paga.`),family:'descuento'};
  if(level===3)return {...q(topic,level,`Un producto, tras aumentar un ${a}%, cuesta ${b*(1+a/100)} €. ¿Cuál era su precio antes del aumento?`,b,`Precio inicial x: x·${fmt(1+a/100)}=${fmt(b*(1+a/100))} ⇒ x=${b}.`,`No restes el porcentaje sobre el precio final: deshaz el factor.`),family:'precio-original'};
  if(level===4){c=pick([10,20,25]);return {...q(topic,level,`Una prenda cuesta ${b} € y su precio baja a ${b*(1-a/100)} €. ¿Qué porcentaje de subida posterior sobre el nuevo precio devolvería el precio original? (Responde en %.)`,100*a/(100-a),`Factor inverso: ${b}/${fmt(b*(1-a/100))}. Subida = ${fmt(100*a/(100-a))}%.`,`El porcentaje de recuperación se calcula sobre el precio rebajado.`),family:'reversion'};}
  c=pick([10,15,20]);return {...q(topic,level,`El precio final de un artículo con descuento del ${a}% es ${fmt(b*(1-a/100))} €. Antes del descuento se añadió una tasa fija de ${c} € al precio base. ¿Cuál era el precio base?`,b-c,`Antes del descuento era ${b} €. Precio base ${b}−${c}=${b-c} €.`,`Primero invierte el descuento y después quita la tasa fija.`),family:'precio-con-tasa'};
 }
 if(topic==='porc_encadenados'){
  a=pick([10,20,25]);b=pick([10,20]);c=randint(5,15)*40;
  ans=c*(1-a/100)*(1+b/100);
  if(level===1)return {...q(topic,level,`Un artículo cuesta ${c} €. Primero baja un ${a}% y después sube un ${b}% respecto al precio rebajado. ¿Precio final?`,ans,`${c}·${fmt(1-a/100)}·${fmt(1+b/100)}=${fmt(ans)} €.`,`Cada porcentaje se aplica sobre el valor actualizado.`),family:'baja-sube'};
  if(level===2)return {...q(topic,level,`Un capital de ${c} € aumenta un ${a}% y luego otro ${b}%. ¿Cuánto queda?`,c*(1+a/100)*(1+b/100),`${c}·${fmt(1+a/100)}·${fmt(1+b/100)}=${fmt(c*(1+a/100)*(1+b/100))} €.`,`No sumes directamente los dos porcentajes.`),family:'doble-aumento'};
  if(level===3)return {...q(topic,level,`Una prenda de ${c} € recibe dos descuentos sucesivos del ${a}% y ${b}%. ¿Cuánto se paga?`,c*(1-a/100)*(1-b/100),`${c}·${fmt(1-a/100)}·${fmt(1-b/100)}=${fmt(c*(1-a/100)*(1-b/100))} €.`,`Multiplica los factores restantes.`),family:'doble-descuento'};
  if(level===4)return {...q(topic,level,`Un precio de ${c} € sube un ${a}% y luego baja un ${a}%. ¿Cuántos euros menos que al principio queda?`,c*(a/100)**2,`Factor final (1+${a}/100)(1−${a}/100)=1−(${a}/100)². Pérdida ${fmt(c*(a/100)**2)} €.`,`Subir y bajar el mismo porcentaje no se anulan.`),family:'sube-baja-igual'};
  return {...q(topic,level,`Una tienda vende a ${fmt(ans)} € tras rebajar un ${a}% y añadir luego un ${b}% sobre el precio rebajado. ¿Cuál era el precio inicial?`,c,`Precio inicial = ${fmt(ans)}/[${fmt(1-a/100)}·${fmt(1+b/100)}]=${c} €.`,`Invierte los dos factores multiplicativos.`),family:'deshacer-cadena'};
 }
 if(topic==='reparto_directo'){
  a=randint(2,7);b=randint(2,7);c=randint(2,7);k=randint(3,20);total=(a+b)*k;
  if(level===1)return {...q(topic,level,`Reparte ${total} € entre dos personas en proporción ${a}:${b}. ¿Cuánto recibe la primera?`,a*k,`Hay ${a+b} partes de ${k} €; primera ${a*k} €.`,`Calcula primero el valor de una parte.`),family:'dos-partes'};
  if(level===2)return {...q(topic,level,`Se reparten ${total} puntos proporcionalmente a las aportaciones ${a} y ${b}. ¿Cuántos recibe la segunda persona?`,b*k,`Valor por unidad de aportación ${total}/(${a+b})=${k}; segunda ${b*k}.`,`Cada aportación recibe el mismo importe por unidad.`),family:'aportaciones'};
  if(level===3){total=(a+b+c)*k;return {...q(topic,level,`Reparte ${total} € en proporción ${a}:${b}:${c}. ¿Cuánto corresponde al tercer participante?`,c*k,`Total ${a+b+c} partes; cada una vale ${k} €. Tercero ${c*k} €.`,`Suma las tres razones.`),family:'tres-partes'};}
  if(level===4){total=(a+b+c)*k;return {...q(topic,level,`Tres socios aportan ${a*100} €, ${b*100} € y ${c*100} €. Se reparten ${total} € de beneficio proporcionalmente al capital. ¿Cuánto más recibe el tercero que el primero?`,(c-a)*k,`Partes ${a}:${b}:${c}; diferencia (${c}−${a})·${k}=${(c-a)*k} €.`,`Primero calcula cuánto corresponde a cada socio.`),family:'beneficio-diferencia'};}
  total=(a+b+c)*k;return {...q(topic,level,`Un premio de ${total} € se reparte según las contribuciones ${a}:${b}:${c}. Si la segunda persona dona la mitad de su parte, ¿cuántos euros conserva?`,b*k/2,`Segunda parte ${b*k} €. Conserva ${fmt(b*k/2)} €.`,`Calcula el reparto antes de la donación.`),family:'reparto-condicion'};
 }
 if(topic==='reparto_inverso'){
  // Razones inversas 1/a : 1/b; se expresan como b:a, evitando redondeos.
  a=randint(2,7);b=randint(2,7);k=randint(3,16);total=(a+b)*k;
  if(level===1)return {...q(topic,level,`Se reparten ${total} € de modo inversamente proporcional a ${a} y ${b}. ¿Cuánto recibe la primera persona?`,b*k,`Pesos inversos: 1/${a}:1/${b}=${b}:${a}. Hay ${a+b} partes de ${k} €; primera ${b*k}.`,`Invierte las razones antes de repartir.`),family:'inverso-dos'};
  if(level===2)return {...q(topic,level,`Dos participantes tardan ${a} y ${b} horas en una tarea y se reparte una prima de ${total} € inversamente a los tiempos. ¿Cuánto recibe quien tardó ${b} horas?`,a*k,`Reparto según 1/${a}:1/${b}=${b}:${a}. La persona de ${b} h recibe ${a*k} €.`,`Quien tarda menos recibe una proporción mayor.`),family:'tiempos'};
  if(level===3){c=randint(2,6);let m=a*b*c;total=(b*c+a*c+a*b)*k;return {...q(topic,level,`Reparte ${total} puntos inversamente a ${a}, ${b} y ${c}. ¿Cuánto recibe la tercera persona?`,a*b*k,`Multiplicando los pesos 1/${a}, 1/${b}, 1/${c} por ${m} obtenemos ${b*c}:${a*c}:${a*b}. Parte tercera ${a*b*k}.`,`Usa el producto de los tres números para obtener pesos enteros.`),family:'inverso-tres'};}
  if(level===4){c=randint(2,6);total=(b*c+a*c+a*b)*k;return {...q(topic,level,`Tres corredores tienen marcas de ${a}, ${b} y ${c} minutos. Se reparte una ayuda de ${total} € inversamente al tiempo. ¿Cuánto reciben conjuntamente los dos primeros?`,(b*c+a*c)*k,`Pesos: ${b*c}:${a*c}:${a*b}; suma de dos primeras partes ${fmt((b*c+a*c)*k)} €.`,`Calcula las razones inversas y suma las dos cuotas.`),family:'tres-suma'};}
  c=randint(2,6);total=(b*c+a*c+a*b)*k;return {...q(topic,level,`Se reparten ${total} € inversamente a tres tiempos ${a}, ${b} y ${c}. ¿Cuál es la diferencia entre lo que cobra la primera persona y la tercera? (Diferencia con signo.)`,(b*c-a*b)*k,`Pesos ${b*c}:${a*c}:${a*b}. Diferencia primera−tercera: (${b*c}−${a*b})·${k}=${(b*c-a*b)*k} €.`,`Transforma primero los inversos en pesos enteros.`),family:'tres-diferencia'};
 }
 throw Error('Apartado de proporcionalidad no disponible');
}


// Generadores específicos por subtema. Enunciados parametrizados y claves exactas.
function makeNew(topic,level){
 const a=randint(2,8),b=randint(2,9),c=randint(2,7),d=randint(2,6),n=randint(3,9),k=Math.max(1,level-1);
 if(topic==='decimales'){
  const eur=randint(2,25),cents=randint(11,95),cent=eur*100+cents,other=randint(15,85),units=randint(2,8),money=n=>fmt(n/100);
  if(level===1){const ans=cent+other;return {...q(topic,level,`Calcula con decimales: ${money(cent)} + ${money(other)}.`,ans/100,`${money(cent)} + ${money(other)} = ${money(ans)}. Alinea las comas decimales.`,`Coloca unidades, décimas y centésimas en columnas.`),family:'decimales-suma'};}
  if(level===2&&Math.random()<0.35){const ans=Math.round(cent/10)/10;return {...q(topic,level,`Redondea ${money(cent)} a las décimas (una cifra decimal).`,ans,`La centésima determina el redondeo a décimas: ${money(cent)} ≈ ${fmt(ans)}.`,`Mira la cifra de las centésimas.`),family:'decimales-aproximacion'};}
  if(level===2){const ans=cent-other;return {...q(topic,level,`Calcula: ${money(cent)} − ${money(other)}.`,ans/100,`${money(cent)} − ${money(other)} = ${money(ans)}.`,`Alinea las comas y completa con ceros si hace falta.`),family:'decimales-resta'};}
  if(level===3&&Math.random()<0.35){const ans=cent*2;return {...q(topic,level,`Calcula: ${money(cent)} ÷ 0,5.`,ans/100,`${money(cent)} ÷ 0,5 = ${money(ans)}. Dividir entre 0,5 equivale a multiplicar por 2.`,`Piensa cuántas mitades caben en el número.`),family:'decimales-division'};}
  if(level===3){const ans=cent*units;return {...q(topic,level,`Una tienda vende ${units} artículos a ${money(cent)} € cada uno. ¿Cuánto se paga en total?`,ans/100,`${units} × ${money(cent)} = ${money(ans)} €.`,`Multiplica en céntimos y expresa después en euros.`),family:'decimales-multiplicacion'};}
  if(level===4){const t=randint(3,7),x=t*randint(10,35),tot=cent*t+x;return {...q(topic,level,`Un grupo compra ${t} entradas a ${money(cent)} € cada una y paga ${money(x)} € de gestión. Reparten el coste en partes iguales entre ${t} personas. ¿Cuánto paga cada una?`,tot/(100*t),`Total: ${t} × ${money(cent)} + ${money(x)} = ${money(tot)} €. Entre ${t} personas: ${money(tot/t)} €.`,`Primero calcula el gasto total y luego divide.`),family:'decimales-dos-pasos'};}
  const base=randint(11,39)*100,percent=randint(1,4)*5,final=base*(100-percent)/100;return {...q(topic,level,`Una factura de ${money(base)} € tiene un descuento del ${percent} %. Después se añade un coste fijo de ${money(other)} €. ¿Cuál es el importe final?`,(final+other)/100,`Descuento: ${money(base)} × ${percent}/100 = ${money(base*percent/100)} €. Total: ${money(final)} + ${money(other)} = ${money(final+other)} €.`,`El descuento afecta a la factura inicial; el coste fijo se añade después.`),family:'decimales-porcentajes'};
 }
 if(topic==='notacion'){
  const pow=randint(2,5),coef=randint(2,9),coef2=randint(2,8);
  if(level<=2)return {...q(topic,level,`Calcula: ${coef} × 10^${pow}.`,coef*10**pow,`${coef}·10^${pow}=${coef*10**pow}.`,'Multiplica el coeficiente por la potencia de diez.'),family:'forma-decimal'};
  if(level===3)return {...q(topic,level,`Calcula: (${coef} × 10³) + (${coef2} × 10³).`,(coef+coef2)*1000,`(${coef}+${coef2})·1000=${(coef+coef2)*1000}.`,'Extrae el factor 10³.'),family:'suma-cientifica'};
  if(level===4)return {...q(topic,level,`Calcula: (${coef} × 10^${pow}) ÷ (${coef2} × 10²).`,coef/coef2*10**(pow-2),`(${coef}/${coef2})·10^${pow-2}=${fmt(coef/coef2*10**(pow-2))}.`,'Divide coeficientes y resta exponentes.'),family:'division-cientifica'};
  const grams=coef*10**pow;return {...q(topic,level,`Un laboratorio consume ${coef} × 10^${pow} gramos de material en ${coef2} días. ¿Cuántos gramos consume por día a ritmo constante?`,grams/coef2,`${grams}/${coef2}=${fmt(grams/coef2)} g/día.`,'Expresa primero la cantidad total.'),family:'problema-cientifico'};
 }
 if(topic==='monomios'){
  const x=randint(2,5);
  if(level<=2)return {...q(topic,level,`Si x=${x}, calcula ${a}x².`,a*x*x,`${a}·${x}²=${a*x*x}.`,'Primero calcula la potencia.'),family:'valor-monomio'};
  if(level===3)return {...q(topic,level,`Reduce: ${a}x + ${b}x − ${c}x. ¿Cuál es el coeficiente final?`,a+b-c,`(${a}+${b}−${c})x = ${a+b-c}x.`,'Agrupa términos semejantes.'),family:'reducir-monomios'};
  if(level===4)return {...q(topic,level,`Multiplica ${a}x² · ${b}x³. ¿Cuál es el coeficiente del monomio resultante?`,a*b,`${a*b}x⁵: multiplica coeficientes y suma exponentes.`,'La pregunta pide el coeficiente, no el grado.'),family:'producto-monomios'};
  return {...q(topic,level,`Para x=${x}, calcula ${a}x² − ${b}x + ${c}.`,a*x*x-b*x+c,`${a}·${x*x}−${b}·${x}+${c}=${a*x*x-b*x+c}.`,'Sustituye y respeta el orden de operaciones.'),family:'expresion-mixta'};
 }
 if(topic==='polinomios'){
  const x=randint(2,5);
  if(level<=2)return {...q(topic,level,`Reduce: (${a}x + ${b}) + (${c}x − ${d}). ¿Cuál es el término independiente?`,b-d,`Se obtiene (${a+c})x + (${b-d}).`,'Agrupa las constantes.'),family:'suma-polinomios'};
  if(level===3)return {...q(topic,level,`Calcula el valor de P(x)=${a}x² − ${b}x + ${c} para x=${x}.`,a*x*x-b*x+c,`P(${x})=${a}·${x*x}−${b}·${x}+${c}=${a*x*x-b*x+c}.`,'Sustituye toda aparición de x.'),family:'valor-polinomio'};
  if(level===4)return {...q(topic,level,`Desarrolla (${a}x + ${b})(x − ${c}). ¿Cuál es el coeficiente de x?`,b-a*c,`${a}x² + (${b-a*c})x − ${b*c}.`,'Distribuye ambos factores.'),family:'producto-polinomio'};
  return {...q(topic,level,`Para x=${x}, calcula (${a}x − ${b})² − (${a}x + ${c})(${a}x − ${c}).`,(a*x-b)**2-((a*x)**2-c*c),`Sustituye x=${x}; diferencia de cuadrados y cuadrado de binomio. Resultado ${((a*x-b)**2-((a*x)**2-c*c))}.`,'Puedes simplificar antes de sustituir.'),family:'identidades-aplicadas'};
 }
 if(topic==='coordenadas'){
  const x=randint(-8,-2),y=randint(2,8),dx=a,dy=b;
  if(level<=2)return {...q(topic,level,`El punto A(${x}, ${y}) se desplaza ${dx} unidades hacia la derecha. ¿Cuál es su nueva abscisa?`,x+dx,`x=${x}+${dx}=${x+dx}.`,'La abscisa es la primera coordenada.'),family:'traslacion'};
  if(level===3)return {...q(topic,level,`Los puntos A(${x}, ${y}) y B(${x+dx}, ${y}) tienen la misma ordenada. ¿Cuánto mide el segmento AB?`,dx,`Distancia horizontal=${x+dx}−(${x})=${dx}.`,'Resta las abscisas.'),family:'distancia-horizontal'};
  if(level===4)return {...q(topic,level,`A(${x}, ${y}) y B(${x+dx}, ${y+dy}) son vértices opuestos de un rectángulo con lados paralelos a los ejes. ¿Cuál es su área?`,dx*dy,`Base=${dx}, altura=${dy}; área=${dx*dy}.`,'Calcula diferencias absolutas.'),family:'rectangulo-coordenadas'};
  return {...q(topic,level,`A(${x}, ${y}), B(${x+dx}, ${y}) y C(${x+dx}, ${y+dy}) son vértices de un triángulo rectángulo. ¿Cuál es su área?`,dx*dy/2,`Catetos=${dx},${dy}; área=${fmt(dx*dy/2)}.`,'Busca base y altura perpendiculares.'),family:'triangulo-coordenadas'};
 }
 if(topic==='lineales'){
  const x=randint(3,8),m=randint(2,6),z=randint(-6,6);
  if(level<=2)return {...q(topic,level,`Para y=${m}x, ¿cuánto vale y cuando x=${x}?`,m*x,`y=${m}·${x}=${m*x}.`,'Sustituye x.'),family:'lineal-evaluar'};
  if(level===3)return {...q(topic,level,`Una recta pasa por A(0, ${z}) y B(${x}, ${m*x+z}). ¿Cuál es su pendiente?`,m,`m=(${m*x+z}−${z})/${x}=${m}.`,'Divide incremento vertical entre horizontal.'),family:'pendiente'};
  if(level===4)return {...q(topic,level,`Dos tarifas tienen costes C₁(t)=${m}t+${a} y C₂(t)=${m+1}t+${a-x}. ¿Para qué valor de t cuestan lo mismo?`,x,`Igualando: ${m}t+${a}=(${m+1})t+(${a-x}); t=${x}.`,'Iguala los costes y despeja.'),family:'interseccion'};
  return {...q(topic,level,`Una recta pasa por A(0, ${z}) y B(${x}, ${m*x+z}). Calcula f(${x+3}) si es una función afín.`,m*(x+3)+z,`Pendiente=${m}; f(t)=${m}t+(${z}); f(${x+3})=${m*(x+3)+z}.`,'Encuentra antes la pendiente.'),family:'modelar-recta'};
 }
 if(topic==='estadistica'){
  const data=[a,b,c,d],sum=data.reduce((x,y)=>x+y,0);
  if(level<=2)return {...q(topic,level,`¿Cuál es la media de ${data.join(', ')}?`,sum/4,`Media=${sum}/4=${fmt(sum/4)}.`,'Suma y divide entre cuatro.'),family:'media'};
  if(level===3){const dat=[a,a,b,c,c].sort((x,y)=>x-y);return {...q(topic,level,`Halla la mediana de los datos ${dat.join(', ')}.`,dat[2],`Ordena y elige el tercer valor: ${dat[2]}.`,'Con cinco datos la mediana es el valor central.'),family:'mediana'};}
  if(level===4)return {...q(topic,level,`En un grupo hay ${a} estudiantes con nota ${b} y ${c} con nota ${d}. ¿Cuál es la media del grupo?`,(a*b+c*d)/(a+c),`Media ponderada=(${a}·${b}+${c}·${d})/(${a}+${c})=${fmt((a*b+c*d)/(a+c))}.`,'Pondera por número de alumnos.'),family:'media-ponderada'};
  return {...q(topic,level,`Las puntuaciones ${a}, ${b}, ${c}, ${d} aumentan todas en ${n} puntos. ¿En cuánto aumenta la media?`,n,`Sumar ${n} a cada dato añade ${n} a su media.`,'Piensa cómo cambia la suma total.'),family:'propiedad-media'};
 }
 if(topic==='pitagoras'){
  const triples=[[3,4,5],[5,12,13],[8,15,17],[7,24,25]],factor=randint(1,9),t=pick(triples).map(v=>v*factor);
  if(level<=2)return {...q(topic,level,`Un triángulo rectángulo tiene catetos ${t[0]} y ${t[1]} cm. ¿Cuánto mide la hipotenusa?`,t[2],`h²=${t[0]}²+${t[1]}²=${t[2]**2}; h=${t[2]}.`,'La hipotenusa es el lado mayor.'),family:'hipotenusa'};
  if(level===3)return {...q(topic,level,`Una escalera de ${t[2]} m se apoya con la base a ${t[0]} m de la pared. ¿A qué altura llega?`,t[1],`h²=${t[2]**2}−${t[0]**2}=${t[1]**2}; h=${t[1]}.`,'La escalera es la hipotenusa.'),family:'cateto'};
  if(level===4)return {...q(topic,level,`Una parcela rectangular mide ${t[0]*2} m por ${t[1]*2} m. ¿Cuánto mide su diagonal?`,2*t[2],`d=√(${2*t[0]}²+${2*t[1]}²)=${2*t[2]} m.`,'La diagonal crea dos triángulos rectángulos.'),family:'diagonal'};
  return {...q(topic,level,`Un cable de ${t[2]*2} m va desde la parte superior de un poste hasta un punto a ${t[0]*2} m de su base. ¿Cuál es la altura del poste?`,2*t[1],`h=√(${(2*t[2])**2}−${(2*t[0])**2})=${2*t[1]} m.`,'Plantea una relación de Pitágoras con incógnita.'),family:'cable'};
 }
 if(topic==='semejanza'){
  if(level<=2)return {...q(topic,level,`Un plano está a escala 1:${a*100}. ¿Cuántos metros reales representan ${b} cm?`,a*b,`${b}·${a*100} cm=${a*b} m.`,'Convierte cm a m al final.'),family:'escala'};
  if(level===3)return {...q(topic,level,`Dos figuras semejantes tienen razón de longitudes ${a}. Si una longitud original mide ${b} cm, ¿cuánto mide la correspondiente ampliada?`,a*b,`${a}·${b}=${a*b} cm.`,'Las longitudes se multiplican por la razón.'),family:'longitud-semejante'};
  if(level===4)return {...q(topic,level,`En figuras semejantes la razón de longitudes es ${a}. Un área pequeña mide ${b} cm². ¿Cuál es el área correspondiente grande?`,a*a*b,`Las áreas cambian con el cuadrado de la razón: ${a}²·${b}=${a*a*b} cm².`,'Distingue escala lineal de escala superficial.'),family:'area-semejante'};
  return {...q(topic,level,`Una torre proyecta sombra de ${a*b} m; una vara de ${b} m proyecta sombra de ${c} m al mismo instante. ¿Qué altura tiene la torre?`,a*b*b/c,`Por semejanza h/${a*b}=${b}/${c}; h=${fmt(a*b*b/c)} m.`,'Relaciona altura y sombra de cada objeto.'),family:'tales-contexto'};
 }
 if(topic==='superficies'){
  const l=randint(3,9),w=randint(3,8),h=randint(2,7);
  if(level<=2)return {...q(topic,level,`Un cubo tiene arista de ${l} cm. ¿Cuál es su área total en cm²?`,6*l*l,`6·${l}²=${6*l*l} cm².`,'Son seis caras iguales.'),family:'cubo-area'};
  if(level===3)return {...q(topic,level,`Un prisma rectangular mide ${l}, ${w} y ${h} cm. ¿Cuál es su área total?`,2*(l*w+l*h+w*h),`A=2(lw+lh+wh)=${2*(l*w+l*h+w*h)} cm².`,'Cada par de caras se repite.'),family:'prisma-area'};
  if(level===4)return {...q(topic,level,`Un cilindro tiene radio ${l} cm y altura ${h} cm. Su área lateral es A=kπ cm². Calcula el coeficiente entero k.`,2*l*h,`A=2πrh=2·${l}·${h}·π=${2*l*h}π cm². Por tanto, k=${2*l*h}.`,'Desarrolla la superficie lateral como un rectángulo.'),family:'cilindro-lateral-exacto'};
  return {...q(topic,level,`Un cilindro tiene radio ${l} cm y altura ${h} cm. Su área total es A=kπ cm². Calcula el coeficiente entero k.`,2*l*(l+h),`A=2πr(r+h)=2·${l}·(${l}+${h})π=${2*l*(l+h)}π cm². Por tanto, k=${2*l*(l+h)}.`,'Suma las áreas de las dos bases al área lateral.'),family:'cilindro-total-exacto'};
 }
 if(topic==='volumen'){
  const l=randint(2,7),w=randint(2,8),h=randint(3,9);
  if(level<=2)return {...q(topic,level,`Calcula el volumen de un prisma rectangular de dimensiones ${l}, ${w} y ${h} cm.`,l*w*h,`V=${l}·${w}·${h}=${l*w*h} cm³.`,'Multiplica el área de la base por la altura.'),family:'prisma-volumen'};
  if(level===3)return {...q(topic,level,`Una pirámide de base cuadrada tiene lado ${l} cm y altura ${h} cm. ¿Qué volumen ocupa?`,l*l*h/3,`V=${l}²·${h}/3=${fmt(l*l*h/3)} cm³.`,'El volumen es un tercio del prisma correspondiente.'),family:'piramide'};
  if(level===4)return {...q(topic,level,`Un cilindro tiene radio ${l} cm y altura ${h} cm. Su volumen es V=kπ cm³. Calcula el coeficiente entero k.`,l*l*h,`V=πr²h=π·${l}²·${h}=${l*l*h}π cm³. Por tanto, k=${l*l*h}.`,'Calcula el cuadrado del radio y multiplica por la altura.'),family:'cilindro-volumen-exacto'};
  return {...q(topic,level,`Un depósito rectangular mide ${l} m por ${w} m y tiene ${h} m de altura. Está lleno a 2/3. ¿Cuántos m³ contiene?`,l*w*h*2/3,`V total=${l*w*h} m³; contenido=2/3·${l*w*h}=${fmt(l*w*h*2/3)} m³.`,'Primero calcula el volumen total.'),family:'volumen-fraccion'};
 }
 throw Error('Subtema sin generador: '+topic);
}

function make(topic,level){if(EXTRA_TOPICS.some(t=>t.id===topic))return makeNew(topic,level);if(PROP_IDS.includes(topic))return makeProportion(topic,level);if(ALGEBRA_IDS.includes(topic))return makeAlgebra(topic,level);let a,b,c,d,x,y,v;
 switch(topic){
 case 'enteros':switch(level){
 case 1:a=randint(-18,-4);b=randint(5,20);return q(topic,level,`Calcula: ${a} + ${b}`,a+b,`Suma cantidades con signo distinto y conserva el signo de la de mayor valor absoluto. Resultado: ${a+b}.`,'Compara los valores absolutos.');
 case 2:a=randint(3,9);b=randint(2,7);c=randint(1,6);return q(topic,level,`Calcula: ${a} − ${b} × ${c}`,a-b*c,`Primero multiplicamos: ${b} × ${c} = ${b*c}. Después ${a} − ${b*c} = ${a-b*c}.`,'Prioriza la multiplicación.');
 case 3:a=randint(3,8);b=randint(2,6);c=randint(3,8);return q(topic,level,`Calcula: −${a} + ${b} × (${c} − ${a+1})`,-a+b*(c-a-1),`Paréntesis: ${c}-${a+1}=${c-a-1}. Producto: ${b}·(${c-a-1})=${b*(c-a-1)}. Suma: ${-a+b*(c-a-1)}.`,'Orden: paréntesis, producto, suma.');
 case 4:a=randint(3,12);b=randint(2,7);c=randint(1,8);return q(topic,level,`Una temperatura era de −${a} °C. Sube ${b} °C por hora durante 3 horas y después baja ${c} °C. ¿Cuál es la temperatura final?`,-a+3*b-c,`−${a}+3·${b}−${c} = ${-a+3*b-c} °C.`,'Representa cada cambio como suma o resta.');
 default:a=randint(3,7);b=randint(2,5);c=randint(2,5);return q(topic,level,`Calcula: (${a} − ${b})² − ${c} × (${a} − ${b} − 3)`,(a-b)**2-c*(a-b-3),`(${a-b})²=${(a-b)**2}; ${c}·(${a-b-3})=${c*(a-b-3)}. Diferencia: ${(a-b)**2-c*(a-b-3)}.`,'Respeta el orden y los signos.');}
 case 'fracciones':switch(level){
 case 1:a=randint(1,5);b=randint(2,7);c=randint(1,5);d=randint(2,7);v=a/b+c/d;return q(topic,level,`Calcula: ${a}/${b} + ${c}/${d}`,v,`Denominador común ${b*d}: (${a*d}+${c*b})/${b*d} = ${fmt(v)}.`,'Busca un denominador común.');
 case 2:a=randint(2,6);b=randint(3,8);c=randint(2,5);d=randint(3,8);v=(a/b)*(c/d);return q(topic,level,`Calcula: (${a}/${b}) × (${c}/${d})`,v,`Producto de numeradores y de denominadores: ${a*c}/${b*d} = ${fmt(v)}.`,'Multiplica numeradores entre sí y denominadores entre sí.');
 case 3:a=randint(1,4);b=randint(2,7);c=randint(1,4);d=randint(2,6);v=a/b+(c/d)*2;return q(topic,level,`Calcula: ${a}/${b} + 2 × (${c}/${d})`,v,`Producto: ${2*c}/${d}. Después se suman las fracciones: ${fmt(v)}.`,'Multiplica antes de sumar.');
 case 4:a=1;b=randint(4,8);c=1;d=randint(4,8);v=1-a/b-c/d;return q(topic,level,`Se consume ${a}/${b} de un depósito por la mañana y ${c}/${d} por la tarde. ¿Qué fracción del depósito queda?`,v,`Queda 1−${a}/${b}−${c}/${d} = ${fmt(v)} del depósito.`,'Empieza por la unidad completa.');
 default:a=randint(1,4);b=randint(3,7);c=randint(1,4);d=randint(2,6);v=(a/b+c/d)/(2/3);return q(topic,level,`Calcula: (${a}/${b} + ${c}/${d}) ÷ (2/3)`,v,`Primero ${a}/${b}+${c}/${d} = ${fmt(a/b+c/d)}. Dividir entre 2/3 es multiplicar por 3/2. Resultado: ${fmt(v)}.`,'Resuelve primero el paréntesis.');}
 case 'potencias':switch(level){
 case 1:a=randint(3,12);return q(topic,level,`Calcula ${a}²`,a*a,`${a}² = ${a} × ${a} = ${a*a}.`,'Multiplica la base por sí misma.');
 case 2:a=randint(2,5);b=randint(2,4);c=randint(1,3);return q(topic,level,`Calcula: ${a}${'⁰¹²³⁴⁵⁶⁷⁸⁹'[b]} × ${a}${'⁰¹²³⁴⁵⁶⁷⁸⁹'[c]}`,a**(b+c),`Potencias de igual base: se suman exponentes, ${a}^${b+c} = ${a**(b+c)}.`,'Busca una base común.');
 case 3:a=randint(2,6);b=randint(2,3);return q(topic,level,`Calcula: (${a}²)³ ÷ ${a}⁴`,a*a,`(${a}²)³=${a}⁶. Dividimos: ${a}⁶/${a}⁴ = ${a}² = ${a*a}.`,'Potencia de potencia y cociente de igual base.');
 case 4:a=randint(6,12);b=randint(2,5);return q(topic,level,`Calcula: √${a*a} + ${b}³ − ${a}`,b**3,`√${a*a}=${a}; ${b}³=${b**3}. ${a}+${b**3}−${a}=${b**3}.`,'La raíz cuadrada principal no es negativa.');
 default:a=randint(2,9);b=randint(2,7);return q(topic,level,`En notación científica, ( ${a} × 10³ ) × ( ${b} × 10² ) representa ¿qué número entero?`,a*b*100000,`${a}×${b}×10⁵ = ${a*b}×100000 = ${a*b*100000}.`,'Agrupa coeficientes y potencias de diez.');}
 case 'proporcionalidad':switch(level){
 case 1:a=randint(2,5);b=randint(3,8);c=randint(2,5);return q(topic,level,`Si ${a} cuadernos cuestan ${a*b} €, ¿cuánto cuestan ${a+c} cuadernos al mismo precio?`,(a+c)*b,`Precio por cuaderno: ${b} €. Total: ${a+c}·${b} = ${(a+c)*b} €.`,'Calcula primero el precio unitario.');
 case 2:a=pick([10,15,20,25,30]);b=randint(40,150);return q(topic,level,`Calcula el ${a}% de ${b} €.`,a*b/100,`${a}/100·${b} = ${fmt(a*b/100)} €.`,'El porcentaje es una fracción de 100.');
 case 3:a=pick([10,20,25]);b=pick([10,20]);c=randint(5,15)*20;v=c*(1-a/100)*(1+b/100);return q(topic,level,`Un artículo cuesta ${c} €. Se rebaja un ${a}% y después sube un ${b}% sobre el precio rebajado. ¿Cuál es el precio final?`,v,`${c}·${fmt(1-a/100)}·${fmt(1+b/100)} = ${fmt(v)} €.`,'Los porcentajes sucesivos no se suman.');
 case 4:a=randint(3,6);b=randint(4,9);c=randint(2,6);return q(topic,level,`${a} trabajadores tardan ${b} días en terminar un trabajo al mismo ritmo. ¿Cuántos días necesitan ${a*c} trabajadores?`,b/c,`El trabajo total es constante: ${a}·${b}=${a*c}·d. Por tanto d=${fmt(b/c)} días.`,'Más trabajadores implica menos días.');
 default:a=randint(3,6);b=randint(3,6);c=randint(2,4);d=randint(2,4);return q(topic,level,`${a} máquinas fabrican ${a*b*8} piezas en 8 horas. ¿Cuántas piezas fabrican ${a+c} máquinas en ${8+d} horas al mismo ritmo?`,b*(a+c)*(8+d),`Rendimiento: ${b} piezas por máquina y hora. Total ${b}·${a+c}·${8+d} = ${b*(a+c)*(8+d)}.`,'Busca la producción por máquina y por hora.');}
 case 'geometria':switch(level){
 case 1:a=randint(5,18);b=randint(3,12);return q(topic,level,`Un rectángulo mide ${a} cm de largo y ${b} cm de ancho. Calcula su perímetro (cm).`,2*(a+b),`P=2·(${a}+${b})=${2*(a+b)} cm.`,'Suma las longitudes de sus cuatro lados.');
 case 2:a=randint(5,15);b=randint(4,14);return q(topic,level,`Calcula el área de un triángulo de base ${a} cm y altura ${b} cm (en cm²).`,a*b/2,`A=base·altura/2=${a}·${b}/2=${fmt(a*b/2)} cm².`,'El triángulo ocupa la mitad del rectángulo correspondiente.');
 case 3:a=pick([3,5,6,8,9,12]);b=a===3?4:a===5?12:a===6?8:a===8?15:a===9?12:16;return q(topic,level,`Catetos de un triángulo rectángulo: ${a} cm y ${b} cm. ¿Cuánto mide la hipotenusa?`,Math.hypot(a,b),`Por Pitágoras, h²=${a*a}+${b*b}=${a*a+b*b}. h=${fmt(Math.hypot(a,b))} cm.`,'La hipotenusa es el lado mayor.');
 case 4:a=randint(2,5);b=randint(3,8);c=randint(2,5);return q(topic,level,`Un plano a escala 1:${a*100} representa un camino de ${b} cm. ¿Cuántos metros mide el camino real?`,a*b,`${b}×${a*100} cm = ${a*b*100} cm = ${a*b} m.`,'Convierte centímetros a metros.');
 default:a=randint(3,9);b=randint(4,10);return q(topic,level,`Los puntos A(1, 2) y B(${a+1}, ${b+2}) son vértices de un rectángulo de lados paralelos a los ejes. ¿Cuál es su área (u²)?`,a*b,`Las diferencias horizontales y verticales son ${a} y ${b}. Área = ${a}·${b} = ${a*b} u².`,'Busca las diferencias de coordenadas.');}
 case 'funciones':switch(level){
 case 1:a=randint(2,6);b=randint(1,7);x=randint(2,6);return q(topic,level,`Si f(x)=${a}x+${b}, calcula f(${x}).`,a*x+b,`f(${x})=${a}·${x}+${b}=${a*x+b}.`,'Sustituye x por el valor indicado.');
 case 2:a=randint(2,5);b=randint(-5,5);x=randint(1,8);return q(topic,level,`En la función y=${a}x${b<0?' − '+(-b):' + '+b}, ¿cuánto vale y cuando x=${x}?`,a*x+b,`Sustituir: y=${a}·${x}+(${b})=${a*x+b}.`,'Sustituye sin cambiar el signo del término independiente.');
 case 3:a=randint(2,7);b=randint(-7,7);return q(topic,level,`Una recta pasa por (0, ${b}) y (3, ${3*a+b}). ¿Cuál es su pendiente?`,a,`Pendiente = (${3*a+b}−(${b}))/(3−0) = ${a}.`,'La pendiente mide el cambio en y por unidad de x.');
 case 4:a=randint(2,7);b=randint(1,6);x=randint(2,8);return q(topic,level,`¿En qué valor de x se cortan las rectas y=${a}x+${b} e y=${a+1}x${b-x<0?' − '+(x-b):' + '+(b-x)}?`,x,`Igualamos: ${a}x+${b}=(${a+1})x+${b-x}. Despejando x=${x}.`,'En la intersección ambas funciones tienen la misma y.');
 default:a=randint(2,6);b=randint(-4,7);x=randint(2,7);return q(topic,level,`Una función afín pasa por A(0, ${b}) y B(${x}, ${a*x+b}). ¿Qué valor tiene f(${x+2})?`,a*(x+2)+b,`La pendiente es (${a*x+b}−(${b}))/${x}=${a}. Así f(t)=${a}t+(${b}); f(${x+2})=${a*(x+2)+b}.`,'Calcula primero pendiente y ordenada en el origen.');}
 case 'datos':switch(level){
 case 1:a=randint(3,9);b=randint(3,9);c=randint(3,9);return q(topic,level,`Halla la media de ${a}, ${b} y ${c}.`,(a+b+c)/3,`(${a}+${b}+${c})/3 = ${fmt((a+b+c)/3)}.`,'Suma todos los datos y divide por su cantidad.');
 case 2:a=randint(2,7);b=randint(7,12);c=randint(13,19);return q(topic,level,`Calcula la mediana de los datos ${c}, ${a}, ${b}.`,b,`Ordenados: ${a}, ${b}, ${c}. El valor central es ${b}.`,'Ordena los datos.');
 case 3:a=randint(4,8);b=randint(5,9);c=randint(2,4);return q(topic,level,`Dos pruebas cuentan respectivamente un 40% y un 60%. Las notas son ${a} y ${b}. ¿Cuál es la media ponderada?`,a*.4+b*.6,`${a}·0,4+${b}·0,6=${fmt(a*.4+b*.6)}.`,'Una media ponderada no siempre es la media simple.');
 case 4:a=randint(3,7);b=randint(2,6);return q(topic,level,`Una bolsa tiene ${a} bolas rojas y ${b} azules. Se extraen dos sin reposición. ¿Cuál es la probabilidad de sacar dos rojas?`,a/(a+b)*(a-1)/(a+b-1),`P = ${a}/${a+b}·${a-1}/${a+b-1} = ${fmt(a/(a+b)*(a-1)/(a+b-1))}.`,'Tras la primera extracción queda una bola menos.');
 default:a=randint(3,8);b=randint(2,7);return q(topic,level,`En un juego ganas ${a} puntos con probabilidad 1/4 y pierdes ${b} puntos con probabilidad 3/4. ¿Cuál es la ganancia media esperada por partida?`,a/4-3*b/4,`Valor esperado = ${a}·(1/4)−${b}·(3/4) = ${fmt(a/4-3*b/4)} puntos.`,'Pondera ganancias y pérdidas por sus probabilidades.');}
 }
 throw Error('Tema o nivel no disponible');}
function numberValue(s){const t=String(s||'').trim().replace(/−/g,'-').replace(/\s/g,'').replace(',','.');if(/^[-+]?\d+(?:\.\d+)?\/[-+]?\d+(?:\.\d+)?$/.test(t)){const [n,d]=t.split('/').map(Number);return d!==0?n/d:null}return /^[-+]?\d+(?:\.\d+)?$/.test(t)?Number(t):null}
function near(a,b){return Math.abs(a-b)<Math.max(1e-7,Math.abs(b)*1e-7)}
function mastery(topic){const old=state.attempts.filter(a=>a.topic===topic&&a.mode==='practice');let level=3,pass=0,fail=0;for(const a of old){if(a.independent&&a.level===level){pass++;fail=0;if(pass>=3&&level<5){level++;pass=0}}else if(!a.correct&&a.level===level){fail++;pass=0;if(fail>=2&&level>1){level--;fail=0}}}return level}
function currentLevel(topic){return Math.max(1,Math.min(5,mastery(topic)))}
// La práctica debe ofrecer reto: niveles 3–5 son la propuesta habitual.
// Dos fallos recientes bajan temporalmente la exigencia, sin devolver al
// alumnado de refuerzo a una batería casi exclusiva de ejercicios básicos.
function practiceLevel(topic){
 const base=currentLevel(topic), recent=state.attempts.filter(a=>a.topic===topic&&a.mode==='practice').slice(-4);
 const fails=recent.filter(a=>!a.correct).length;
 if(fails>=2){const r=Math.random();return r<.60?3:r<.90?4:5}
 const weights=base>=5?[.10,.30,.60]:base===4?[.15,.40,.45]:base===3?[.25,.40,.35]:[.20,.45,.30,.05];
 const levels=base>=3?[3,4,5]:[2,3,4,5];
 let r=Math.random(),i=0;for(;i<weights.length-1&&r>=weights[i];i++)r-=weights[i];return levels[i];
}
function setTheme(level){const x=LEVELS[level-1]||LEVELS[2];document.documentElement.style.setProperty('--accent',x.color);document.documentElement.style.setProperty('--wash',x.wash);document.documentElement.style.setProperty('--accentDark','#283d54');}
function newQuestion(topic=state.topic){state.topic=topic;const lv=practiceLevel(topic);state.active={...safeQuestion(topic,lv),tries:0,hintShown:false,feedback:null,created:stamp()};save()}
function start(topic){newQuestion(topic);view='practica';render()}
function record(correct,entered,skipped=false){const a=state.active;if(!a||a.feedback)return;const independent=correct&&a.tries===1&&!a.hintShown;const attempt={topic:a.topic,level:a.level,mode:'practice',time:stamp(),independent,correct,tries:a.tries,hints:a.hintShown?1:0,skipped,stem:a.stem,answered:String(entered||''),expected:fmt(a.answer)};state.attempts.push(attempt);a.feedback={correct,independent,skipped};save();render()}
function respond(){const a=state.active;if(!a||a.feedback)return;const entered=$('#response')?.value||'';const n=numberValue(entered);if(n===null){$('#notice').textContent='Escribe un número entero o una fracción (por ejemplo, 3/4).' ;return}a.tries++;const correct=near(n,a.answer);if(correct){record(true,entered)}else if(a.tries>=2){record(false,entered)}else{a.lastWrong=entered;save();render()}}
function progressFor(t){const list=state.attempts.filter(a=>a.topic===t);return {n:list.length,free:list.filter(a=>a.independent).length,level:currentLevel(t),recent:list.slice(-5)}}
function button(id,text,cls=''){return `<button id="${id}" class="button ${cls}" type="button">${esc(text)}</button>`}
function practice(){if(!state.active)newQuestion();const a=state.active;setTheme(a.level);const p=progressFor(a.topic);return `<div class="eyebrow">Practicar · ${esc(T[a.topic].name)}</div><h1>Ejercicios a tu nivel</h1>${bridge2(a.topic)}<section class="panel"><div class="cols"><label class="field">Seleccionar tema<select id="topicSelect">${groupOptions(a.topic)}</select></label><div class="field"><span>Tu nivel en este tema</span><span class="pill" style="align-self:start;margin-top:8px">${a.level}/5 · ${LEVELS[a.level-1].name}</span><span class="tiny muted">Los niveles pueden ser distintos en cada tema. ${T[a.topic].stage==='AMPLIACION'?'Este subtema es de ampliación hacia 3.º ESO.':''}</span></div></div><div class="tiles">${LEVELS.map((l,i)=>`<div title="Nivel ${i+1}: ${l.name}" class="tile" style="background:${i<a.level?l.color:'#e7ebef'}"></div>`).join('')}</div><p class="tiny muted">${p.n} ejercicios previos en este tema · ${p.free} correctos sin pistas · Se sube por evidencia, no por edad ni etiqueta.</p><hr class="sep"><div class="qtitle">${prettyStem(a.stem)}</div>${a.feedback?`<div class="answer ${a.feedback.correct?'':'bad'}"><b>${a.feedback.correct?'Respuesta correcta.':'Vamos a revisar este procedimiento.'}</b><p>Resultado: <strong>${esc(fmt(a.answer))}</strong></p><p>${esc(a.solution)}</p></div><div class="actions">${button('next','Siguiente ejercicio')}</div>`:`<form id="answerForm"><label class="field">Respuesta<input id="response" inputmode="text" autocomplete="off" placeholder="Ej.: 12 o 3/4" aria-label="Respuesta"></label><div id="notice" class="tiny" role="status"></div>${a.lastWrong!==undefined?'<div class="alert">Todavía no coincide. Puedes volver a intentarlo o pedir una pista.</div>':''}${a.hintShown?`<div class="hint"><b>Pista:</b> ${esc(a.hint)}</div>`:''}<div class="actions"><button class="button" type="submit">Comprobar</button>${button('hint','Mostrar pista','alt')}${button('skip','No lo sé','light')}</div></form>`}</section><p class="muted small">El nivel 5 incluye ampliación inicial/intermedia de 3.º ESO. No es una calificación ni un diagnóstico. Las pistas impiden contar un acierto como autónomo.</p>`}
function progress(){setTheme(3);const all=state.attempts,days=new Set(all.map(a=>keyday(a.time)));return `<div class="eyebrow">Seguimiento individual</div><h1>Mi progreso</h1><div class="three"><div class="kpi"><strong>${days.size}</strong><small>Días con actividad</small></div><div class="kpi"><strong>${all.length}</strong><small>Ejercicios intentados</small></div><div class="kpi"><strong>${all.filter(x=>x.independent).length}</strong><small>Resueltos autónomamente</small></div></div><section class="panel"><h2>Nivel por tema</h2>${TOPICS.map(t=>{const x=progressFor(t.id),c=LEVELS[x.level-1].color;return `<div class="topicrow"><div style="flex:1"><b>${t.name}</b><div class="meter"><span style="width:${x.level*20}%;background:${c}"></span></div><span class="tiny muted">${x.n} intentos · ${x.free} autónomos</span></div><b class="tag" style="background:${LEVELS[x.level-1].wash}">Nivel ${x.level}/5</b></div>`}).join('')}</section><section class="panel"><h2>Últimos intentos</h2>${all.length?`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">Fecha</th><th align="left">Tema</th><th align="left">Nivel</th><th align="left">Resultado</th></tr></thead><tbody>${all.slice(-15).reverse().map(a=>`<tr><td style="padding:8px;border-bottom:1px solid #ddd">${date(a.time)}</td><td>${esc(T[a.topic]?.name||a.topic)}</td><td>${a.level}/5</td><td>${a.independent?'Autónomo':a.correct?'Con ayuda':'Para revisar'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Sin actividad registrada.</p>'}</section><p class="note">La subida se calcula por tema mediante tres aciertos autónomos en el nivel actual; dos errores permiten bajar para reforzar. Es una regla de práctica, no una prueba psicométrica. La retención a varios días debe valorarse con distintas sesiones.</p>`}
