for(const [topic,items] of Object.entries(OPEN_BANK)){if(topic===NO_DECIMAL_TOPIC){delete OPEN_BANK[topic];continue;}OPEN_BANK[topic]=items.filter(noDecimalContent);}
function shuffle(a){const z=[...a];for(let i=z.length-1;i>0;i--){let j=randint(0,i);[z[i],z[j]]=[z[j],z[i]]}return z}
function inverseOptions(x){
 const n=x.answer;if(!Number.isSafeInteger(n)||n<=0)throw Error('Respuesta inversa no válida');
 const v=x.verification||{};const candidates=[n+1,n-1,2*n,Math.ceil(n/2),n+2,n+3,v.t1,v.t2,v.v1,v.v2,v.time1,v.time2];
 const values=[n];for(const c of shuffle(candidates)){if(Number.isSafeInteger(c)&&c>0&&!values.includes(c)){values.push(c);if(values.length===4)break;}}
 for(let c=1;values.length<4;c++)if(!values.includes(c))values.push(c);
 return shuffle(values.map(c=>({label:String(c),correct:c===n})));
}
function optionsFor(x){if(x.topic==='prop_inversa')return inverseOptions(x);const n=x.answer,base=Math.max(1,Math.abs(n)),diff=base>100?Math.max(2,Math.round(base*.12)):base>15?Math.max(2,Math.round(base*.14)):base>2?2:0.25;const candidates=[n+diff,n-diff,-n,n+diff*2,n-diff*2,n*2,n/2,n+1,n-1,n+3];const opts=[n];for(const val of shuffle(candidates)){if(Number.isFinite(val)&&opts.every(x=>!near(x,val))){opts.push(val);if(opts.length===4)break}}while(opts.length<4){const val=n+(opts.length+1)*7;if(opts.every(x=>!near(x,val)))opts.push(val)}return shuffle(opts.map(val=>({label:fmt(val),correct:near(val,n)})))}
function makeVaried(topic,level){
 if(ALGEBRA_IDS.includes(topic)||PROP_IDS.includes(topic))return make(topic,level);
 const choice=randint(0,3);let a=randint(2,12),b=randint(2,9),c=randint(2,8),v;
 if(choice===0){const it=make(topic,level);return {...it,family:'original-'+level};}
 if(topic==='enteros'){
  if(choice===1){v=-a+2*b-c;return {...q(topic,level,`Un marcador parte de −${a}, gana ${b} puntos dos veces y pierde ${c}. ¿Con qué puntuación termina?`,v,`−${a}+2·${b}−${c}=${v}.`,'Representa los cambios con signo.'),family:'contexto'};}
  if(choice===2){v=(a-b)*c-2*a;return {...q(topic,level,`Calcula: (${a}−${b})·${c}−2·${a}`,v,`(${a-b})·${c}−${2*a}=${v}.`,'Respeta la jerarquía.'),family:'jerarquia'};}
  v=-a+b*(c-2);return {...q(topic,level,`Calcula: −${a}+${b}·(${c}−2)`,v,`−${a}+${b}·${c-2}=${v}.`,'Primero el paréntesis.'),family:'mixtas'};
 }
 if(topic==='fracciones'){
  if(choice===1){v=1/a+1/b;return {...q(topic,level,`¿Qué parte de una unidad representan 1/${a}+1/${b}?`,v,`(${a+b})/${a*b}=${fmt(v)}.`,'Suma fracciones con denominador común.'),family:'suma'};}
  if(choice===2){v=1-(1/a+1/b);return {...q(topic,level,`De una unidad se utilizan 1/${a} y 1/${b}. ¿Qué parte queda?`,v,`1−1/${a}−1/${b}=${fmt(v)}.`,'Resta de la unidad.'),family:'resto'};}
  v=(a/b)*(c/2);return {...q(topic,level,`Calcula (${a}/${b})·(${c}/2).`,v,`${a*c}/${b*2}=${fmt(v)}.`,'Multiplica numeradores y denominadores.'),family:'producto'};
 }
 if(topic==='potencias'){
  if(choice===1){v=2**a/2**b;return {...q(topic,level,`Calcula 2^${a} ÷ 2^${b}.`,v,`2^(${a}−${b})=${fmt(v)}.`,'Cociente de igual base.'),family:'cociente'};}
  if(choice===2){v=(a**2)-(b**2);return {...q(topic,level,`Calcula ${a}² − ${b}².`,v,`${a*a}−${b*b}=${v}.`,'Calcula cada potencia.'),family:'cuadrados'};}
  v=3**(randint(2,4));let m=Math.round(Math.log(v)/Math.log(3));return {...q(topic,level,`Calcula (3²)^${m} ÷ 3^${m}.`,3**m,`3^(2·${m}−${m})=3^${m}=${3**m}.`,'Potencia de potencia.'),family:'potencia-potencia'};
 }
 if(topic==='proporcionalidad'){
  if(choice===1){const percent=randint(10,35),price=randint(5,20)*20;v=price*(1-percent/100);return {...q(topic,level,`Un artículo de ${price} € tiene un descuento del ${percent} %. ¿Cuánto se paga?`,v,`${price}·${fmt(1-percent/100)}=${fmt(v)} €.`,'Multiplica por el porcentaje restante.'),family:'descuento'};}
  if(choice===2){const p=randint(4,9),days=randint(3,8);return {...q(topic,level,`${p} personas tardan ${days*2} días en un trabajo. Si trabajan ${p*2} personas al mismo ritmo, ¿cuántos días tardarán?`,days,`${p}·${days*2}=${p*2}·d⇒d=${days}.`,'Trabajo constante.'),family:'inversa'};}
  const m=randint(3,9),rate=randint(2,7);v=(m+3)*rate;return {...q(topic,level,`${m} cuadernos cuestan ${m*rate} €. ¿Cuánto cuestan ${m+3} al mismo precio?`,v,`Precio unitario ${rate}; coste ${v}.`,'Calcula el precio unitario.'),family:'directa'};
 }
 if(topic==='geometria'){
  if(choice===1){v=a*b;return {...q(topic,level,`Un rectángulo mide ${a} cm por ${b} cm. Calcula su área en cm².`,v,`A=${a}·${b}=${v}.`,'Producto de lados.'),family:'area'};}
  if(choice===2){v=2*(a+b);return {...q(topic,level,`Un rectángulo tiene lados ${a} y ${b} cm. ¿Cuál es su perímetro?`,v,`P=2(${a}+${b})=${v}.`,'Suma los cuatro lados.'),family:'perimetro'};}
  v=3*a;return {...q(topic,level,`A escala 1:300, ${a} cm representan ¿cuántos metros reales?`,v,`${a}·300 cm=${a*300} cm=${v} m.`,'Convierte de cm a m.'),family:'escala'};
 }
 if(topic==='funciones'){
  if(choice===1){v=a*b+c;return {...q(topic,level,`La función f(x)=${a}x+${c}. Calcula f(${b}).`,v,`${a}·${b}+${c}=${v}.`,'Sustitución.'),family:'evaluar'};}
  if(choice===2){v=a;return {...q(topic,level,`Una recta pasa por (0,${c}) y (2,${2*a+c}). ¿Cuál es su pendiente?`,v,`(${2*a+c}−${c})/2=${a}.`,'Calcula la variación relativa.'),family:'pendiente'};}
  v=b;return {...q(topic,level,`Un servicio cuesta ${c} € fijos y ${a} € por unidad. Si el total es ${a*b+c} €, ¿cuántas unidades se usaron?`,v,`${a}x+${c}=${a*b+c}⇒x=${b}.`,'Plantea la ecuación.'),family:'inversa-funcion'};
 }
 if(topic==='datos'){
  if(choice===1){v=(a+b+c)/3;return {...q(topic,level,`Las puntuaciones son ${a}, ${b}, ${c}. ¿Cuál es la media?`,v,`Suma y divide entre tres: ${fmt(v)}.`,'Media aritmética.'),family:'media'};}
  if(choice===2){v=a/(a+b);return {...q(topic,level,`En una urna hay ${a} bolas rojas y ${b} azules. ¿Cuál es la probabilidad de sacar una roja?`,v,`${a}/${a+b}=${fmt(v)}.`,'Casos favorables entre totales.'),family:'probabilidad'};}
  v=(a*2+b*3)/5;return {...q(topic,level,`En una prueba con peso 2 se obtiene ${a}; en otra con peso 3 se obtiene ${b}. ¿Cuál es la media ponderada?`,v,`(2·${a}+3·${b})/5=${fmt(v)}.`,'Pondera según los pesos.'),family:'ponderada'};
 }
 return make(topic,level);
}
function openFor(topic,level,seen){
 const curated=DOCUMENTED_BANK.filter(x=>x.topic===topic&&x.level===level&&!seen.has(x.stem)&&noDecimalContent(x));
 if(curated.length){const x=pick(curated);seen.add(x.stem);return {...x,type:'open',bankId:x.id,sourceType:'original'};}
 const options=(OPEN_BANK[topic]||[]).filter(x=>x.level===level&&!seen.has(x.stem)&&noDecimalContent(x));
 if(options.length){const v=pick(options);seen.add(v.stem);return {...v,topic,level,type:'open'};}
 // Los ejercicios abiertos nuevos se construyen como problemas de razonamiento,
 // nunca se presentan como un enunciado repetido del mismo examen.
 for(let i=0;i<50;i++){const v=safeQuestion(topic,level);if(!seen.has(v.stem)){seen.add(v.stem);return {...v,topic,level,type:'open',stem:v.stem+' Explica el procedimiento y comprueba tu respuesta.'};}}
 throw Error('Banco insuficiente para este tema');
}
function integerGeometry(topic,level){
 const a=randint(4,12),b=randint(3,9),h=randint(3,10);
 if(topic==='coordenadas'){
  const x=randint(-8,2),y=randint(-6,2),w=randint(5,12),v=randint(4,10);
  return {...q(topic,level,`Los puntos A(${x}; ${y}), B(${x+w}; ${y}), C(${x+w}; ${y+v}) y D(${x}; ${y+v}) son vértices de una figura. Calcula su área.`,w*v,`Es un rectángulo de lados ${w} y ${v}; su área es ${w*v} unidades cuadradas.`,`Calcula primero la longitud de sus dos lados.`),family:'coordenadas-rectangulo'};
 }
 if(topic==='superficies'){
  const total=2*(a*b+a*h+b*h);
  return {...q(topic,level,`Una caja cerrada tiene forma de prisma rectangular, con dimensiones ${a} cm, ${b} cm y ${h} cm. ¿Cuántos cm² de cartón se necesitan para construirla sin solapas?`,total,`Área total = 2(${a}·${b}+${a}·${h}+${b}·${h})=${total} cm².`,`Calcula las áreas de las tres parejas de caras iguales.`),family:'superficie-prisma'};
 }
 if(topic==='volumen'){
  const v=a*b*h;
  return {...q(topic,level,`Un depósito de forma prismática mide interiormente ${a} dm de largo, ${b} dm de ancho y ${h} dm de alto. ¿Cuántos litros contiene lleno?`,v,`Volumen=${a}·${b}·${h}=${v} dm³; un dm³ es un litro.`,`Calcula primero el volumen en dm³.`),family:'volumen-prisma'};
 }
 throw Error('Sin plantilla de geometría');
}
function safeQuestion(topic,level,allowVaried=false){
 if(topic===NO_DECIMAL_TOPIC)throw Error('No se generan ejercicios con números decimales.');
 for(let i=0;i<220;i++){
  const qx=allowVaried?makeVaried(topic,level):make(topic,level);
  if(noDecimalContent(qx))return qx;
 }
 if(['coordenadas','superficies','volumen'].includes(topic))return integerGeometry(topic,level);
 // La familia de ejercicios debe permitir enteros o fracciones exactas.
 throw Error('No se encontró un enunciado sin decimales para este contenido. Cambia el subtema.');
}
function bankTopicCount(id){return DOCUMENTED_BANK.filter(x=>x.topic===id).length}
function examGenerate(topicIds){
 const topics=[...new Set(topicIds)].filter(x=>T[x]&&x!==NO_DECIMAL_TOPIC);if(topics.length<1||topics.length>7)throw Error('Elige entre 1 y 7 contenidos concretos');
 const items=[],seen=new Set(),families={};let order=shuffle(topics);
 for(let i=0;i<10;i++){
  const topic=order[i%order.length],level=i%2===0?3:4,tag=topic+'-'+level;
  const used=families[tag]||(families[tag]=new Set());let item=null,choices=[];
  for(let k=0;k<160;k++){const cand=safeQuestion(topic,level,true);if(!seen.has(cand.stem)){if(!used.has(cand.family||cand.stem.slice(0,35)))choices.push(cand);else if(!item)item=cand;}}
  item=choices.length?pick(choices):item;
  if(!item)throw Error('No hay suficientes ejercicios distintos en el banco');
  seen.add(item.stem);used.add(item.family||item.stem.slice(0,35));
  items.push({...item,type:'test',options:optionsFor(item)});
 }
 const opens=[];for(let i=0;i<3;i++){const topic=order[(i+1)%order.length],level=i===0?4:5;opens.push(openFor(topic,level,seen));}
 return {id:'ex-'+Date.now(),time:stamp(),topics,items,opens,title:'Examen de Matemáticas · 2.º ESO',answers:{},submitted:false,mark:null};
}
// Notación matemática en MathML nativo (compatible con Safari/Chrome, sin conexión ni API).
// Un pequeño conversor de expresiones aritméticas a MathML. No usa HTML de entradas del alumnado.
const mathEsc=t=>esc(t);
function expressionMath(raw){
 const src=String(raw).replaceAll('−','-').replaceAll('×','·').replaceAll('÷','/');let i=0;
 const nodes=[];const token=()=>{const c=src[i];if(!c)return '';
  if(c==='('){i++;const inside=[];while(i<src.length&&src[i]!==')')inside.push(token());if(src[i]===')')i++;return `<mrow><mo>(</mo>${inside.join('')}<mo>)</mo></mrow>`;}
  if(c==='√'){i++;let arg;if(src[i]==='('){arg=token();}else{let q='';while(i<src.length&&/[0-9]/.test(src[i]))q+=src[i++];arg=`<mn>${mathEsc(q||'?')}</mn>`;}return `<msqrt>${arg}</msqrt>`;}
  if(/\s/.test(c)){i++;return '<mspace width="0.20em"/>';}
  if(/[0-9]/.test(c)){let n='';while(i<src.length&&/[0-9,.]/.test(src[i]))n+=src[i++];return `<mn>${mathEsc(n)}</mn>`;}
  if(/[a-zA-Z]/.test(c)){i++;return `<mi>${mathEsc(c)}</mi>`;}
  i++;return `<mo>${mathEsc(c)}</mo>`;
 };
 // Extract a fraction numerator from the just-built tokens. For example (x-3)/4 or x/3.
 while(i<src.length){
  if(src[i]==='/'&&nodes.length){i++;while(src[i]===' ')i++;const prev=nodes.pop();let den='';if(src[i]==='('){den=token();}else{while(i<src.length&&/[0-9a-zA-Z]/.test(src[i]))den+=token();}
   nodes.push(`<mfrac>${prev}<mrow>${den||'<mn>1</mn>'}</mrow></mfrac>`);continue;}
  if(src[i]==='²'||src[i]==='³'||src[i]==='^'){const mark=src[i++];let e=mark==='²'?'2':mark==='³'?'3':'';if(!e)while(/[0-9]/.test(src[i]||''))e+=src[i++];const prev=nodes.pop()||'<mi>x</mi>';nodes.push(`<msup>${prev}<mn>${mathEsc(e||'2')}</mn></msup>`);continue;}
  nodes.push(token());
 }
 return `<math xmlns="http://www.w3.org/1998/Math/MathML" display="inline"><mrow>${nodes.join('')}</mrow></math>`;
}
function prettyStem(t){const txt=String(t);const idx=txt.indexOf('Resuelve: ');if(idx>=0){const before=txt.slice(0,idx+10),f=txt.slice(idx+10);return `${esc(before)} <span class="mathline">${expressionMath(f)}</span>`;}
 const calc=txt.indexOf('Calcula: ');if(calc>=0){return esc(txt.slice(0,calc+9))+` <span class="mathline">${expressionMath(txt.slice(calc+9))}</span>`;}
 const matched=txt.match(/(\([^()]{1,25}\)\/\d+|\b\d+\/\d+|\bx\/\d+)/);
 // Fraction-bearing problem text keeps accessible prose; replace short clear fraction groups only.
 if(matched){let pos=0,out='';for(const m of txt.matchAll(/\([^()]{1,35}\)\/\d+|\b\d+\/\d+|\bx\/\d+/g)){out+=esc(txt.slice(pos,m.index))+expressionMath(m[0]);pos=m.index+m[0].length;}return out+esc(txt.slice(pos));}
 return esc(txt);
}

function examView(){setTheme(4);if(!state.exam)return `<div class="eyebrow">Generador de exámenes · sin IA</div><h1>Preparar un examen</h1><section class="panel"><h2>Elige entre 1 y 7 contenidos concretos</h2><p class="muted small">Genera <b>10 preguntas tipo test (niveles 3 y 4)</b> y <b>3 ejercicios abiertos (niveles 4 y 5)</b>, con solucionario separado. Los ejercicios abiertos requieren corrección docente.</p><div class="boxes">${topicChecks()}</div><p class="tiny muted" id="chosenCount">2 temas seleccionados.</p><div class="actions">${button('generateExam','Generar examen')}</div><div id="exError" class="muted small" role="status"></div></section><section class="panel"><h2>Cómo se utiliza</h2><p>El examen se puede resolver en pantalla (autocorrección de las 10 preguntas tipo test) o imprimir como PDF. Los tres ejercicios abiertos se corrigen con el solucionario y la explicación del alumno; no se atribuye automáticamente una calificación a esas respuestas.</p><p class="tiny muted">Los niveles 4–5 son niveles pedagógicos de esta herramienta, no denominaciones oficiales del decreto.</p></section>`;
const e=state.exam;if(examDisplay==='key')return `<div class="screenExam"><div class="examBrand"><img src="marca-angel.png" alt="Marca de Ángel Gil Gómez" onerror="this.hidden=true"><span>© Ángel Gil Gómez</span></div><div class="eyebrow">Solucionario · uso docente</div><h1>Respuestas del examen</h1><p class="muted">© Ángel Gil Gómez · ${date(e.time)}</p><section class="panel"><h2>Test (1–10)</h2>${e.items.map((x,i)=>`<div class="examitem"><b>${i+1}. ${esc(T[x.topic].name)} · nivel ${x.level}</b><p>${prettyStem(x.stem)}</p><p>Respuesta: <b>${'ABCD'[x.options.findIndex(o=>o.correct)]}. ${esc(fmt(x.answer))}</b></p><p class="small">${prettyStem(x.solution)}</p></div>`).join('')}</section><section class="panel pagebreak"><h2>Ejercicios abiertos (11–13)</h2>${e.opens.map((x,i)=>`<div class="examitem"><b>${i+11}. ${esc(T[x.topic].name)} · nivel ${x.level}</b><p>${prettyStem(x.stem)}</p><p><b>Solución esperada:</b> ${esc(typeof x.answer==='number'?fmt(x.answer):x.answer)}</p><p>${prettyStem(x.solution)}</p></div>`).join('')}</section><div class="actions noPrint">${button('examBack','Volver al examen','alt')}${button('printExam','Imprimir solucionario')}</div></div>`;
return `<div class="screenExam"><div class="examBrand"><img src="marca-angel.png" alt="Marca de Ángel Gil Gómez" onerror="this.hidden=true"><span>© Ángel Gil Gómez</span></div><div class="eyebrow">Examen generado · ${date(e.time)}</div><h1>Matemáticas · 2.º ESO</h1><section class="panel"><div class="examHeader"><p><b>Nombre:</b> ________________________</p><p><b>Fecha:</b> __________</p></div><p class="small muted">Temas: ${e.topics.map(t=>T[t].name).join(', ')}. Parte A: 10 preguntas tipo test. Parte B: 3 ejercicios de desarrollo. La escala 1–5 es didáctica; el nivel 5 puede ser ampliación hacia 3.º ESO. Propuestas originales inspiradas en situaciones de diagnósticas de Navarra, no reproducción de pruebas oficiales.</p><h2>Parte A · Test (niveles 3–4)</h2>${e.items.map((x,i)=>`<div class="examitem"><p><b>${i+1}. [Nivel ${x.level}]</b> ${prettyStem(x.stem)}</p><div class="examchoices">${x.options.map((opt,j)=>`<label><input class="noPrint" type="radio" name="q${i}" value="${j}" ${e.answers[i]==j?'checked':''} ${e.submitted?'disabled':''}> <b>${'ABCD'[j]}.</b> ${esc(opt.label)}</label>`).join('')}</div></div>`).join('')}</section><section class="panel"><h2>Parte B · Desarrollo (niveles 4–5)</h2><p class="small muted">Explica el procedimiento, comprueba las operaciones e indica las unidades cuando corresponda.</p>${e.opens.map((x,i)=>`<div class="examitem"><p><b>${11+i}. [Nivel ${x.level}]</b> ${prettyStem(x.stem)}</p><div class="writinglines"></div></div>`).join('')}</section>${e.submitted?`<div class="answer noPrint"><b>Test: ${e.mark}/10</b><p>Resultado de las preguntas tipo test. Los tres ejercicios abiertos están pendientes de corrección docente.</p></div>`:''}<div class="actions noPrint">${!e.submitted?button('examSubmit','Corregir test'):''}${button('printExam','Imprimir / guardar PDF','alt')}${button('examKey','Ver solucionario','alt')}${button('examNew','Crear otro examen','light')}</div><p class="tiny muted noPrint">Si imprimes, las respuestas seleccionadas en pantalla no aparecen en el PDF. El solucionario se imprime por separado.</p><p class="printOnly">© Ángel Gil Gómez · Material didáctico de práctica · DF 71/2022 como referencia normativa</p></div>`}
function family(){setTheme(3);const all=state.attempts,distinct=new Set(all.map(a=>keyday(a.time))).size;const active=all.filter(a=>Date.now()-new Date(a.time).getTime()<7*864e5);const rows=TOPICS.map(t=>{const s=progressFor(t.id);return `<tr><td style="padding:9px;border-bottom:1px solid var(--line)">${esc(t.name)}</td><td>${s.level}/5</td><td>${s.n}</td><td>${s.free}</td></tr>`}).join('');return `<div class="eyebrow">Informe familiar</div><h1>Avance en Matemáticas</h1><p class="muted">Código anónimo: ${esc(state.code)} · ${date(stamp())} · © Ángel Gil Gómez</p><div class="three"><div class="kpi"><strong>${distinct}</strong><small>Días con actividad</small></div><div class="kpi"><strong>${active.length}</strong><small>Intentos en últimos 7 días</small></div><div class="kpi"><strong>${active.filter(a=>a.independent).length}</strong><small>Respuestas autónomas en últimos 7 días</small></div></div><section class="panel"><h2>Contenidos</h2><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">Tema</th><th align="left">Nivel de práctica</th><th align="left">Intentos</th><th align="left">Autónomos</th></tr></thead><tbody>${rows}</tbody></table></div><p class="small muted">Nivel = dificultad que propone el programa según los resultados; no corresponde a una nota oficial ni a un curso acreditado.</p></section><section class="panel"><h2>Problemas abiertos revisados</h2><p>Problemas trabajados: <b>${(state.bankReviews||[]).length}</b>. Declarados resueltos sin ayuda: <b>${(state.bankReviews||[]).filter(a=>a.independent).length}</b>. Es una autoevaluación del alumno, no una corrección docente.</p></section><section class="panel"><h2>Recomendaciones para casa</h2><p>Hacer sesiones breves (10–15 minutos) y revisar errores sin dar la respuesta. Mantener un mismo navegador y perfil, y guardar una copia periódica.</p><p>Los exámenes impresos deben corregirse por el profesor, especialmente los ejercicios abiertos. El programa no registra conductas, diagnósticos de salud ni datos de compañeros.</p><div class="actions noPrint">${button('printFamily','Imprimir / guardar informe PDF')}${button('export','Exportar historial','alt')}</div></section><section class="panel noPrint"><h2>Enviar mis resultados al profesor</h2><p class="small">El envío es voluntario: el alumnado lo realiza al terminar la sesión. La app conserva todo el progreso en este dispositivo. El profesor recibe un resumen de los intentos pendientes, no nombres ni respuestas manuscritas.</p><div class="three"><div class="kpi"><strong>${Math.max(0,all.length-(state.lastSentAttempt||0))}</strong><small>Intentos pendientes</small></div><div class="kpi"><strong>${(state.sentReports||[]).length}</strong><small>Informes confirmados</small></div><div class="kpi"><strong>${state.sentReports?.length?date(state.sentReports[state.sentReports.length-1].time):'—'}</strong><small>Último envío</small></div></div><label class="field">¿Qué he aprendido o qué necesito practicar?<textarea id="reflection" maxlength="240" placeholder="Escribe una frase breve, sin nombres ni datos personales."></textarea></label><label class="check"><input type="checkbox" id="sendConsent"><span>He leído el aviso y confirmo que mi familia conoce este envío de información educativa al profesor. No incluiré datos personales en mi reflexión.</span></label><p class="tiny muted">Solo se envía si pulsas el botón y el servidor confirma la recepción. Requiere Netlify Forms configurado en la publicación, una base jurídica adecuada y un aviso de privacidad facilitado a las familias. No se envía desde una copia local sin publicar.</p><div class="actions">${button('sendReport','Enviar resultados al profesor')}</div><p id="sendStatus" role="status" class="small"></p></section><section class="panel noPrint"><h2>Copias y privacidad</h2><p>El historial permanece <b>únicamente en este navegador</b>. No se sincroniza entre Chromebook, móvil u ordenador. Cada alumno debe usar su propio perfil de navegador; no conviene usar modo invitado.</p><div class="cols"><label class="field">Código anónimo<input id="studentCode" maxlength="12" value="${esc(state.code)}" autocomplete="off" pattern="[A-Za-z0-9-]{1,12}"></label><div class="actions">${button('saveCode','Guardar código','alt')}</div></div><div class="actions">${button('export','Descargar JSON')}${button('import','Importar JSON','alt')}${button('oldImport','Recuperar progreso de versión 2','light')}${button('reset','Borrar progreso','light')}</div><input type="file" accept="application/json,.json" id="importFile" class="hide"><p class="small muted">El JSON contiene un historial educativo: comparte la copia solo con personas autorizadas. La recuperación de versión 2 solo funciona en el navegador donde se utilizó esa versión.</p></section><p class="note noPrint">Los resultados miden respuestas a ejercicios, no capacidades intelectuales ni atención. La aplicación no identifica al alumnado ni envía respuestas a un servidor.</p>`}
async function sendReport(){
 const status=$('#sendStatus'),consent=$('#sendConsent');if(!status)return;
 if(!consent?.checked){status.textContent='Marca la casilla de información a la familia antes de enviar.';return;}
 if(!/^[a-z0-9-]{1,12}$/i.test(state.code)){status.textContent='Introduce antes un código anónimo válido en Familia.';return;}
 const start=Math.max(0,Math.min(state.attempts.length,Number(state.lastSentAttempt)||0)),pending=state.attempts.slice(start);
 if(!pending.length){status.textContent='No hay ejercicios nuevos que enviar.';return;}
 if(location.protocol!=='https:'){status.textContent='El envío solo está disponible desde la web publicada por HTTPS.';return;}
 const note=String($('#reflection')?.value||'').trim().slice(0,240);
 const byTopic={};for(const a of pending){const k=T[a.topic]?.name||a.topic;const b=byTopic[k]||(byTopic[k]={intentados:0,autonomos:0,correctos:0,nivel:0});b.intentados++;b.autonomos+=a.independent?1:0;b.correctos+=a.correct?1:0;b.nivel=Math.max(b.nivel,Number(a.level)||1)}
 const payload={ 'form-name':'seguimiento-refuerzo',codigo:state.code,fecha:stamp(),sesiones:String(new Set(pending.map(a=>keyday(a.time))).size),intentos:String(pending.length),correctos:String(pending.filter(a=>a.correct).length),autonomos:String(pending.filter(a=>a.independent).length),ayudas:String(pending.reduce((z,a)=>z+(Number(a.hints)||0),0)),problemasBanco:String((state.bankReviews||[]).length),temas:JSON.stringify(byTopic).slice(0,3500),reflexion:note};
 const btn=$('#sendReport');if(btn)btn.disabled=true;status.textContent='Enviando...';
 try{const r=await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(payload).toString(),credentials:'same-origin'});
 if(!r.ok)throw Error('El servidor respondió '+r.status);
 state.lastSentAttempt=state.attempts.length;state.sentReports=state.sentReports||[];state.sentReports.push({time:stamp(),count:pending.length,code:state.code});save();render();const e=$('#sendStatus');if(e)e.textContent='Envío aceptado por el servidor. Puedes comprobarlo en el apartado Forms de Netlify.';
 }catch(e){status.textContent='No se ha confirmado el envío ('+e.message+'). Tus datos siguen guardados aquí; vuelve a intentarlo.';if(btn)btn.disabled=false;}
}
function outputJSON(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`refuerzo-2eso-${state.code}-${keyday(stamp())}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function importState(o){if(!o||!Array.isArray(o.attempts)||o.attempts.length>20000)throw Error('Copia incompatible');if(o.version===4||o.version===3){const filtered=o.attempts.filter(x=>(T[x.topic]||x.topic==='algebra')&&x.level>=1&&x.level<=5).map(x=>({...x,topic:x.topic==='algebra'?'eq_basicas':x.topic,stem:String(x.stem||'').slice(0,900),answered:String(x.answered||'').slice(0,200)}));state={...newState(),...o,version:4,attempts:filtered,topic:T[o.topic]?o.topic:'eq_basicas',code:/^[a-z0-9-]{1,12}$/i.test(o.code)?o.code:'A001',active:null,exam:null};return}if(o.version===1){const remap=o.attempts.filter(x=>T[x.topic]||x.topic==='algebra').map(x=>({topic:x.topic==='algebra'?'eq_basicas':x.topic,level:Math.max(1,Math.min(3,Number(x.level)||3)),mode:x.mode||'practice',time:x.time||stamp(),independent:!!x.independent,correct:!!x.correct,tries:Number(x.tries)||1,hints:Number(x.hints)||0,skipped:!!x.skipped,stem:String(x.stem||'').slice(0,900),answered:String(x.answered||'').slice(0,200),expected:String(x.expected||'')}));state={...newState(),code:/^[a-z0-9-]{1,12}$/i.test(o.code)?o.code:'A001',attempts:remap,oldImported:true};return}throw Error('Versión no compatible')}

function bankView(){
 setTheme(4);
 const selected=window.bankUnit||'all',reviewed=state.bankReviews||[];
 const units=UNITS.map((u,i)=>`<option value="${i+1}" ${selected===String(i+1)?'selected':''}>${esc(u.name)}</option>`).join('');
 const list=DOCUMENTED_BANK.filter(x=>noDecimalContent(x)&&(selected==='all'||String(x.unit)===selected));
 return `<div class="eyebrow">Banco propio de problemas · 12 unidades</div><h1>Problemas para pensar</h1><p class="muted">${DOCUMENTED_BANK.length} enunciados originales, inspirados en tipologías de Intergranada y las diagnósticas de Navarra. No son transcripciones literales. Sin decimales.</p><section class="panel"><label class="field">Unidad del libro<select id="bankUnit"><option value="all">Todas las unidades</option>${units}</select></label><p class="small">Resuelve el problema en papel; consulta la solución después y registra si lo has resuelto solo o con ayuda. La aplicación no puntúa automáticamente la explicación escrita.</p><p class="tiny muted">En cada problema: fuente de inspiración, nivel 1–5 y código de referencia. Los niveles son orientativos y no oficiales.</p></section>${list.map(x=>{const done=reviewed.filter(a=>a.bankId===x.id);return `<section class="panel" id="bank-${x.id}"><div class="eyebrow">${esc(UNITS[x.unit-1].name)} · Nivel ${x.level}/5</div><h2>Problema ${esc(x.id)}</h2><p>${prettyStem(x.stem)}</p><p class="tiny muted">Referencia: ${esc(x.source)} (modelo de actividad, no enunciado copiado) · ${esc(T[x.topic]?.name||x.topic)}</p><details><summary><b>Mostrar solución y procedimiento</b></summary><div class="answer"><p><b>Respuesta:</b> ${esc(x.answer)}</p><p>${prettyStem(x.solution)}</p></div></details><div class="actions">${button('bankDone-'+x.id,'Lo he resuelto sin ayuda','alt')}${button('bankHelp-'+x.id,'Necesité ayuda','light')}</div><p class="tiny muted">Registros en este dispositivo: ${done.length}</p></section>`}).join('')}`;
}
function registerBank(id,independent){
 const qx=DOCUMENTED_BANK.find(z=>z.id===id);if(!qx)return;
 state.bankReviews=state.bankReviews||[];
 state.bankReviews.push({bankId:id,topic:qx.topic,level:qx.level,time:stamp(),independent});
 save();render();
}

