function show(v){view=v;render();window.scrollTo(0,0)}
function bind(){const on=(id,fn)=>{const b=$('#'+id);if(b)b.addEventListener('click',fn)};
 const unit=$('#bankUnit');if(unit)unit.addEventListener('change',()=>{window.bankUnit=unit.value;render()});document.querySelectorAll('[id^=bankDone-]').forEach(b=>b.addEventListener('click',()=>registerBank(b.id.slice(9),true)));document.querySelectorAll('[id^=bankHelp-]').forEach(b=>b.addEventListener('click',()=>registerBank(b.id.slice(9),false)));
 const select=$('#topicSelect');if(select)select.addEventListener('change',e=>{if(state.active&&!state.active.feedback&&state.active.tries>0&&!confirm('¿Cambiar de tema y descartar el ejercicio pendiente?')){select.value=state.active.topic;return}start(select.value)});
 const f=$('#answerForm');if(f)f.addEventListener('submit',e=>{e.preventDefault();respond()});on('hint',()=>{if(!state.active||state.active.feedback)return;state.active.hintShown=true;save();render()});on('skip',()=>{if(!state.active||state.active.feedback)return;state.active.tries=Math.max(1,state.active.tries);record(false,'No respondido',true)});on('next',()=>start(state.topic));
 const checkboxes=[...document.querySelectorAll('.exTopic')];if(checkboxes.length){const update=()=>{const n=checkboxes.filter(c=>c.checked).length;$('#chosenCount').textContent=n+' tema'+(n!==1?'s':'')+' seleccionado'+(n!==1?'s':'')+'. Máximo 7.';};checkboxes.forEach(c=>c.addEventListener('change',()=>{if(checkboxes.filter(x=>x.checked).length>7){c.checked=false;$('#exError').textContent='Elige como máximo siete temas.'}else $('#exError').textContent='';update()}));update()}
 on('generateExam',()=>{try{const ids=[...document.querySelectorAll('.exTopic:checked')].map(x=>x.value);state.exam=examGenerate(ids);examDisplay='exam';save();render()}catch(e){$('#exError').textContent=e.message}});
 on('examSubmit',()=>{const e=state.exam;let n=0;e.answers={};e.items.forEach((x,i)=>{const v=document.querySelector(`input[name="q${i}"]:checked`);if(v){const index=Number(v.value);e.answers[i]=index;if(x.options[index]?.correct)n++}});if(Object.keys(e.answers).length!==10&&!confirm('Hay respuestas sin marcar. ¿Corregir igualmente?'))return;e.submitted=true;e.mark=n;state.examHistory.push({time:stamp(),topics:e.topics,score:n,total:10});save();render()});
 on('examKey',()=>{examDisplay='key';render()});on('examBack',()=>{examDisplay='exam';render()});on('examNew',()=>{if(confirm('¿Crear otro examen? Se sustituirá el examen actual (el historial de notas se conserva).')){state.exam=null;examDisplay='exam';save();render()}});on('printExam',()=>window.print());on('printFamily',()=>window.print());on('sendReport',sendReport);on('export',outputJSON);
 on('saveCode',()=>{let v=$('#studentCode').value.trim().toUpperCase();if(!/^[A-Z0-9-]{1,12}$/.test(v)){alert('Utiliza solo código anónimo (letras, números y guiones).');return}state.code=v;save();render()});on('import',()=>$('#importFile').click());const file=$('#importFile');if(file)file.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>4e6)throw Error('Archivo demasiado grande');const obj=JSON.parse(await f.text());if(!confirm('Esto sustituirá los datos de este navegador. ¿Continuar?'))return;importState(obj);newQuestion(state.topic);save();show('practica');alert('Historial importado.')}catch(err){alert('No se pudo importar: '+err.message)}});
 on('oldImport',()=>{const o=localStorage.getItem(OLD);if(!o){alert('No se encuentra progreso de la versión 2 en este navegador. Puedes importar un archivo JSON desde «Importar JSON».');return}if(!confirm('¿Importar el historial de versión 2? Sustituirá el progreso actual; exporta una copia primero.'))return;try{importState(JSON.parse(o));newQuestion();save();show('practica');alert('Historial antiguo recuperado. Las escalas de nivel no son directamente equivalentes.')}catch(e){alert('No se pudo recuperar: '+e.message)}});
 on('reset',()=>{if(confirm('¿Eliminar el historial de este navegador? Exporta antes si lo necesitas.')&&confirm('Confirmación final: esta acción no se puede deshacer sin copia.')){state=newState();newQuestion();save();show('practica')}});
}
