if(!state.active||state.active.topic===NO_DECIMAL_TOPIC||!noDecimalContent(state.active)){newQuestion(state.topic===NO_DECIMAL_TOPIC?'fracciones':state.topic);}if(state.exam?.items?.some(x=>!noDecimalContent(x))||state.exam?.opens?.some(x=>!noDecimalContent(x)))state.exam=null;save();render();if(location.protocol==='https:'&&'serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
window.__MatesTest={make,safeQuestion,examGenerate,OPEN_BANK,TOPICS,DOCUMENTED_BANK,makeVaried,openFor,near,numberValue,mastery,state:()=>state,reset:()=>{state=newState();newQuestion();save();render()}};
